{"command":"function Probe($name, $cmd) {
  Write-Output "=== $name ==="
  try {
    $out = & cmd /c "$cmd 2>&1"
    if ($LASTEXITCODE -eq 0 -or $out) { $out | Select-Object -First 6 }
    Write-Output "exit=$LASTEXITCODE"
  } catch { Write-Output "NOT FOUND / ERROR: $($_.Exception.Message)" }
  Write-Output ""
}
Probe "java -version" "java -version"
Probe "javac -version" "javac -version"
Probe "mvn -v" "mvn -v"
Probe "gradle -v" "gradle -v"
Probe "node -v" "node -v"
Probe "npm -v" "npm -v"
Probe "pnpm -v" "pnpm -v"
Probe "yarn -v" "yarn -v"
Probe "git --version" "git --version"
Probe "docker --version" "docker --version"
Probe "mysql --version" "mysql --version"
Probe "redis-server --version" "redis-server --version"","description":"Probe common dev toolchain versions"}

