{"command":"Write-Output "=== JAVA_HOME / PATH java entries ==="
"JAVA_HOME = $env:JAVA_HOME"
"CLASSPATH = $env:CLASSPATH"
$env:Path -split ';' | Where-Object { $_ -match 'java|jdk|jre|maven|mysql|redis|node|docker' } | ForEach-Object { "PATH> $_" }
Write-Output ""
Write-Output "=== where.exe lookups ==="
foreach ($exe in @('java','javac','mysql','mysqld','redis-server','redis-cli','docker','mongod','psql')) {
  $r = & cmd /c "where $exe 2>nul"
  if ($r) { "$exe -> $($r -join ' | ')" } else { "$exe -> (not on PATH)" }
}
Write-Output ""
Write-Output "=== Common JDK install dirs ==="
$dirs = @('C:\Program Files\Java','C:\Program Files\Eclipse Adoptium','C:\Program Files\Microsoft\jdk','C:\Program Files\Zulu','C:\Program Files\BellSoft','C:\Program Files\Amazon Corretto','C:\Program Files\Common Files\Oracle\Java','D:\Java','D:\jdk','E:\Java','E:\jdk','D:\Program Files\Java','C:\Program Files (x86)\Java')
foreach ($d in $dirs) { if (Test-Path $d) { "FOUND: $d"; Get-ChildItem $d -Directory -ErrorAction SilentlyContinue | Select-Object -First 20 -ExpandProperty Name | ForEach-Object { "    - $_" } } }","description":"Locate Java, MySQL, Docker installations"}

