content.arguments:
{"command":"Write-Output "=== Search for MySQL/MariaDB install dirs (common roots) ==="
$roots = @('C:\Program Files','C:\Program Files (x86)','C:\ProgramData','C:\','D:\','E:\','D:\Program Files','E:\Program Files','C:\tools','D:\tools','D:\dev','E:\dev','D:\G','C:\mysql','D:\mysql','E:\mysql')
foreach ($r in $roots) {
  if (Test-Path $r) {
    Get-ChildItem $r -Directory -ErrorAction SilentlyContinue |
      Where-Object { $_.Name -match 'mysql|maria|wamp|xampp|phpstudy|phpStudy|laragon|sqlyog|navicat|dbeaver|heidi' } |
      ForEach-Object { "  DIR: $($_.FullName)" }
  }
}
Write-Output ""
Write-Output "=== mysqld.exe search on C/D/E (top 3 levels, may take a moment) ==="
$found = @()
foreach ($d in @('C:\','D:\','E:\')) {
  $found += Get-ChildItem -Path $d -Filter 'mysqld.exe' -Recurse -Depth 4 -File -ErrorAction SilentlyContinue | Select-Object -ExpandProperty FullName
}
if ($found) { $found } else { "  mysqld.exe NOT FOUND (depth<=4)" }
Write-Output ""
Write-Output "=== mysql client exe search ==="
$found2 = @()
foreach ($d in @('C:\','D:\','E:\')) {
  $found2 += Get-ChildItem -Path $d -Filter 'mysql.exe' -Recurse -Depth 4 -File -ErrorAction SilentlyContinue | Select-Object -ExpandProperty FullName
}
if ($found2) { $found2 } else { "  mysql.exe NOT FOUND (depth<=4)" }","description":"Deep scan filesystem for MySQL installations","timeoutMs":300000}

{"command":"Write-Output "=== nvm ==="
& cmd /c "nvm list 2>&1"
Write-Output "nvm root: $env:NVM_HOME / $env:NVM_SYMLINK"
Write-Output ""
Write-Output "=== package managers ==="
foreach ($c in @('winget','choco','scoop','pip','python','py')) {
  $r = & cmd /c "$c --version 2>&1"
  if ($LASTEXITCODE -eq 0) { "$c -> $($r | Select-Object -First 1)" } else { "$c -> (not available)" }
}
Write-Output ""
Write-Output "=== LLM local runtimes / API keys ==="
foreach ($c in @('ollama','lms')) {
  $r = & cmd /c "$c --version 2>&1"
  if ($LASTEXITCODE -eq 0) { "$c -> $($r | Select-Object -First 2)" } else { "$c -> (not available)" }
}
Get-ChildItem Env: | Where-Object { $_.Name -match 'API_KEY|OPENAI|ANTHROPIC|DEEPSEEK|DASHSCOPE|QWEN|MOONSHOT|GEMINI|GOOGLE_API|AZURE|LLM|OLLAMA|SILICON' } | ForEach-Object { "ENV $($_.Name) = " + ($_.Value.Substring(0, [Math]::Min(8, $_.Value.Length))) + "..." }
Write-Output "(env scan done)"
Write-Output ""
Write-Output "=== Listening ports of interest ==="
foreach ($p in @(3306,3307,6379,8080,8081,5173,3000,11434,1234,5432)) {
  $c = Get-NetTCPConnection -State Listen -LocalPort $p -ErrorAction SilentlyContinue
  if ($c) { "port $p -> LISTENING (pid $($c[0].OwningProcess) : $((Get-Process -Id $c[0].OwningProcess -ErrorAction SilentlyContinue).ProcessName))" } else { "port $p -> free" }
}","description":"Check nvm, package managers, LLM runtimes, ports"}

