content.arguments:
{"command":"Write-Output "=== Search for MySQL installers / archives anywhere on C/D/E ==="
$pat = '*mysql*','*maria*'
$hits = @()
foreach ($d in @('C:\Users','C:\Users\liujibiao\Downloads','C:\Users\liujibiao\Desktop','D:\','E:\')) {
  if (Test-Path $d) {
    $hits += Get-ChildItem -Path $d -Include $pat -Recurse -Depth 3 -ErrorAction SilentlyContinue | Select-Object -First 30 -ExpandProperty FullName
  }
}
if ($hits) { $hits | Select-Object -Unique -First 40 } else { "  No mysql/maria named files/folders found" }
Write-Output ""
Write-Output "=== Winget: is MySQL available in repos? (search only) ==="
& cmd /c "winget search mysql --accept-source-agreements 2>&1" | Select-Object -First 20","description":"Search for MySQL installers and winget availability","timeoutMs":300000}

