content.arguments:
{"command":"Write-Output "=== Network reachability (package registries) ==="
foreach ($u in @('https://repo.maven.apache.org/maven2/','https://registry.npmjs.org/','https://dev.mysql.com/','https://api.deepseek.com/')) {
  try {
    $sw = [System.Diagnostics.Stopwatch]::StartNew()
    $r = Invoke-WebRequest -Uri $u -Method Head -TimeoutSec 12 -UseBasicParsing -ErrorAction Stop
    "OK   $u  -> HTTP $($r.StatusCode)  ($($sw.ElapsedMilliseconds) ms)"
  } catch {
    "FAIL $u  -> $($_.Exception.Message.Split([Environment]::NewLine)[0])"
  }
}","description":"Test network access to package registries"}

{"command":"Write-Output "=== Git config ==="
& cmd /c "git config --global --list 2>&1" | Select-Object -First 15
Write-Output ""
Write-Output "=== IDEs / Editors ==="
foreach ($p in @('C:\Program Files\JetBrains','C:\Users\liujibiao\AppData\Local\Programs\Microsoft VS Code','C:\Program Files\Microsoft VS Code')) {
  if (Test-Path $p) { "FOUND: $p"; Get-ChildItem $p -Directory -ErrorAction SilentlyContinue | Select-Object -First 10 -ExpandProperty Name | ForEach-Object { "    - $_" } }
}
& cmd /c "code --version 2>&1" | Select-Object -First 2
Write-Output ""
Write-Output "=== Browsers ==="
foreach ($p in @('C:\Program Files\Google\Chrome\Application\chrome.exe','C:\Program Files (x86)\Google\Chrome\Application\chrome.exe','C:\Program Files (x86)\Microsoft\Edge\Application\msedge.exe','C:\Program Files\Microsoft\Edge\Application\msedge.exe')) {
  if (Test-Path $p) { "FOUND: $p" }
}
Write-Output ""
Write-Output "=== Redis service detail ==="
Get-CimInstance Win32_Service -Filter "Name='Redis'" | Select-Object Name, State, StartMode, PathName | Format-List
& cmd /c "D:\G\Redis\redis-cli.exe ping 2>&1"
Write-Output ""
Write-Output "=== Visual C++ Redistributable check for MySQL (needs 2019+) ==="
Get-ChildItem 'HKLM:\SOFTWARE\Microsoft\VisualStudio\14.0\VC\Runtimes\x64' -ErrorAction SilentlyContinue | Out-Null
