content.arguments:
{"command":"Write-Output "=== WSL / virtualization ==="
& cmd /c "wsl -l -v 2>&1" | Select-Object -First 10
Write-Output ""
Write-Output "=== LLM API key config files (existence + masked preview) ==="
$cands = @(
  "$env:USERPROFILE\.cursor\mcp.json",
  "$env:USERPROFILE\.codex\config.toml",
  "$env:USERPROFILE\.codex\auth.json",
  "$env:USERPROFILE\.claude\settings.json",
  "$env:USERPROFILE\.claude.json",
  "$env:USERPROFILE\.continue\config.json",
  "$env:USERPROFILE\.ollama",
  "$env:USERPROFILE\AppData\Roaming\Code\User\settings.json",
  "$env:APPDATA\Trae CN\User\settings.json",
  "$env:USERPROFILE\.trae-cn"
)
foreach ($c in $cands) { if (Test-Path $c) { "EXISTS: $c" } else { "absent: $c" } }
Write-Output ""
Write-Output "=== grep for api keys (masked) in config files ==="
foreach ($f in @("$env:USERPROFILE\.codex\config.toml","$env:USERPROFILE\.codex\auth.json","$env:APPDATA\Code\User\settings.json","$env:APPDATA\Trae CN\User\settings.json")) {
  if (Test-Path $f) {
    $m = Select-String -Path $f -Pattern '(sk-[A-Za-z0-9_\-]{6,})|("?(api[_-]?key|apiKey|OPENAI_API_KEY|DEEPSEEK_API_KEY|ANTHROPIC_API_KEY)"?\s*[:=]\s*"?[^",\s]{6,})' -AllMatches -ErrorAction SilentlyContinue
    if ($m) { "$f : $($m.Count) potential key line(s)"; $m | Select-Object -First 3 | ForEach-Object { "   L$($_.LineNumber): " + ($_.Line.Trim() -replace '(sk-[A-Za-z0-9_\-]{4})[A-Za-z0-9_\-]+','$1***' -replace '([:=]\s*"?)[^",\s]{6,}','$1***') } }
    else { "$f : no key-like patterns" }
  }
}","description":"Check WSL and LLM API key availability"}

