content.arguments:
{"command":"Write-Output "=== codex auth.json key format (prefix only) ==="
$j = Get-Content -Raw "$env:USERPROFILE\.codex\auth.json" | ConvertFrom-Json
$k = $j.OPENAI_API_KEY
if ($k) {
  "length: $($k.Length)"
  "prefix: $($k.Substring(0,[Math]::Min(12,$k.Length)))..."
  if ($k -like 'sk-*') { "looks like: OpenAI-style API key" }
  elseif ($k -like 'eyJ*') { "looks like: JWT / OAuth token (ChatGPT login, NOT a usable API key)" }
  else { "looks like: unknown format" }
} else { "no OPENAI_API_KEY" }
Write-Output ""
Write-Output "=== DSH managed env ==="
Get-ChildItem Env: | Where-Object { $_.Name -like 'DSH_*' } | ForEach-Object { "$($_.Name) = $($_.Value)" }
Write-Output ""
Write-Output "=== DSH config files ==="
foreach ($p in @("$env:USERPROFILE\.dsh","$env:APPDATA\dsh","$env:USERPROFILE\.config\dsh")) { if (Test-Path $p) { "FOUND: $p"; Get-ChildItem $p -Recurse -File -ErrorAction SilentlyContinue | Select-Object -First 20 -ExpandProperty FullName } }","description":"Inspect LLM key format and DSH config"}

