content.arguments:
{"command":"$tmp = "$env:TEMP\webox_envcheck"
if (Test-Path $tmp) { Remove-Item $tmp -Recurse -Force }
New-Item -ItemType Directory -Force -Path "$tmp\src\main\java\com\envcheck" | Out-Null
$pom = @'
<?xml version="1.0" encoding="UTF-8"?>
<project xmlns="http://maven.apache.org/POM/4.0.0" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xsi:schemaLocation="http://maven.apache.org/POM/4.0.0 http://maven.apache.org/xsd/maven-4.0.0.xsd">
  <modelVersion>4.0.0</modelVersion>
  <parent><groupId>org.springframework.boot</groupId><artifactId>spring-boot-starter-parent</artifactId><version>3.2.5</version><relativePath/></parent>
  <groupId>com.envcheck</groupId><artifactId>envcheck</artifactId><version>1.0.0</version>
  <properties><java.version>17</java.version></properties>
  <dependencies>
    <dependency><groupId>org.springframework.boot</groupId><artifactId>spring-boot-starter-web</artifactId></dependency>
    <dependency><groupId>org.springframework.boot</groupId><artifactId>spring-boot-starter-data-jpa</artifactId></dependency>
    <dependency><groupId>com.mysql</groupId><artifactId>mysql-connector-j</artifactId><scope>runtime</scope></dependency>
    <dependency><groupId>org.springframework.boot</groupId><artifactId>spring-boot-starter-data-redis</artifactId></dependency>
    <dependency><groupId>org.springframework.boot</groupId><artifactId>spring-boot-starter-validation</artifactId></dependency>
    <dependency><groupId>org.springframework.boot</groupId><artifactId>spring-boot-starter-test</artifactId><scope>test</scope></dependency>
  </dependencies>
  <build><plugins><plugin><groupId>org.springframework.boot</groupId><artifactId>spring-boot-maven-plugin</artifactId></plugin></plugins></build>
</project>
'@
Set-Content -Path "$tmp\pom.xml" -Value $pom -Encoding utf8
$app = @'
package com.envcheck;
import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.web.bind.annotation.*;
@SpringBootApplication
@RestController
public class App {
  public static void main(String[] a) { SpringApplication.run(App.class, a); }
  @GetMapping("/ping") public String ping() { return "pong"; }
}
'@
Set-Content -Path "$tmp\src\main\java\com\envcheck\App.java" -Value $app -Encoding utf8
Set-Content -Path "$tmp\src\main\resources\application.properties" -Value "" -Encoding utf8 -ErrorAction SilentlyContinue
New-Item -ItemType Directory -Force -Path "$tmp\src\main\resources" | Out-Null
Set-Content -Path "$tmp\src\main\resources\application.properties" -Value "server.port=18080`nspring.main.banner-mode=off" -Encoding utf8
$env:JAVA_HOME='C:\Program Files\Java\jdk-17.0.2'
Set-Location $tmp
Write-Output "### Building Spring Boot 3.2.5 app with JDK 17 ###"
& cmd /c "mvn -B -q clean package -DskipTests 2>&1" | Select-Object -Last 20
Write-Output "BUILD_EXIT=$LASTEXITCODE"
Get-ChildItem "$tmp\target\*.jar" | Select-Object Name, @{n='MB';e={[math]::Round($_.Length/1MB,2)}}
Write-Output ""
Write-Output "### Starting app on :18080 ###"
$p = Start-Process -FilePath "$env:JAVA_HOME\bin\java.exe" -ArgumentList '-jar',"$tmp\target\envcheck-1.0.0.jar" -PassThru -WindowStyle Hidden -RedirectStandardOutput "$tmp\out.log" -RedirectStandardError "$tmp\err.log"
$ok = $false
for ($i=0; $i -lt 40; $i++) {
  Start-Sleep -Milliseconds 1000
  try { $r = Invoke-WebRequest 'http://127.0.0.1:18080/ping' -TimeoutSec 3 -UseBasicParsing -ErrorAction Stop; if ($r.Content -eq 'pong') { $ok = $true; break } } catch {}
