{"command":"Write-Output "=== Who owns the ports ==="
foreach ($p in @(3306,6379,8080,5173)) {
  $c = Get-NetTCPConnection -State Listen -LocalPort $p -EA SilentlyContinue | Select-Object -First 1
  if ($c) { $proc = Get-Process -Id $c.OwningProcess -EA SilentlyContinue; "port $p -> pid $($c.OwningProcess) $($proc.ProcessName)  path=$($proc.Path)" }
}
Write-Output ""
Write-Output "=== MySQL version / process ==="
$mp = Get-Process -Name mysqld -EA SilentlyContinue
if ($mp) { $mp | Select-Object Id, ProcessName, Path, @{n='StartedMinAgo';e={[math]::Round(((Get-Date)-$_.StartTime).TotalMinutes,1)}} | Format-Table -AutoSize }
Get-CimInstance Win32_Service -EA SilentlyContinue | Where-Object { $_.PathName -match 'mysql' } | Select-Object Name, State, StartMode, PathName | Format-List
Write-Output "=== java processes (backend) ==="
