content.arguments:
{"command":"$ErrorActionPreference='Continue'
$base='http://localhost:8080'
function Api($m,$p,$h=@{},$b=$null){
  $pr=@{Method=$m;Uri=$base+$p;Headers=$h;UseBasicParsing=$true}
  if($b){$pr.ContentType='application/json';$pr.Body=($b|ConvertTo-Json -Depth 10 -Compress)}
  try{$r=Invoke-WebRequest @pr; return [pscustomobject]@{S=[int]$r.StatusCode;R=[string]$r.Content}}
  catch{$rp=$_.Exception.Response; if(!$rp){return [pscustomobject]@{S=0;R=$_.Exception.Message}}
    $sr=New-Object IO.StreamReader($rp.GetResponseStream()); return [pscustomobject]@{S=[int]$rp.StatusCode;R=$sr.ReadToEnd()}}
}
$suf=[guid]::NewGuid().ToString('N').Substring(0,8)
$reg=Api POST '/api/auth/register' @{} @{email="audit.$suf@example.com";password="Passw0rd123";displayName="Audit"}
$tok=($reg.R|ConvertFrom-Json).data.token
$H=@{Authorization="Bearer $tok"}
Write-Output "registered: $($reg.S)"

$today=(Get-Date).ToString('yyyy-MM-dd'); $tomorrow=(Get-Date).AddDays(1).ToString('yyyy-MM-dd')
Write-Output ""
Write-Output "=== A. CUT-OFF AUTO-SWITCH (now $(Get-Date -Format HH:mm), both cutoffs passed) ==="
$todayMenu=(Api GET "/api/menu?date=$today&size=50" $H).R|ConvertFrom-Json
$dish=($todayMenu.data.items|Where-Object{$_.optionGroups -eq $null -or $_.optionGroups.Count -eq 0}|Select-Object -First 1)
if(-not $dish){$dish=$todayMenu.data.items[0]}
"using dish: $($dish.name) (id=$($dish.dishId))"

$prev=Api POST '/api/orders/checkout-preview' $H @{items=@(@{dishId=$dish.dishId;quantity=1;optionIds=@()});deliveryDate="$today";mealSlot="Lunch"}
$pj=$prev.R|ConvertFrom-Json
"requested: today=$today Lunch  ->  resolved: date=$($pj.data.resolved.deliveryDate) slot=$($pj.data.resolved.mealSlot) switched=$($pj.data.resolved.switched)"
if($pj.data.resolved.deliveryDate -eq $tomorrow -and $pj.data.resolved.mealSlot -eq 'Lunch'){"[PASS] PRD 4.2: post-cutoff Lunch auto-switched to NEXT-DAY Lunch"}else{"[CHECK] unexpected resolution"}

$prev2=Api POST '/api/orders/checkout-preview' $H @{items=@(@{dishId=$dish.dishId;quantity=1;optionIds=@()});deliveryDate="$today";mealSlot="Dinner"}
$pj2=$prev2.R|ConvertFrom-Json
"requested: today Dinner ->  resolved: date=$($pj2.data.resolved.deliveryDate) slot=$($pj2.data.resolved.mealSlot)"
if($pj2.data.resolved.mealSlot -eq 'Lunch' -and $pj2.data.resolved.deliveryDate -eq $tomorrow){"[PASS] PRD 4.2: post-15:00 Dinner auto-switched to NEXT-DAY Lunch"}else{"[CHECK]"}

Write-Output ""
Write-Output "=== B. FIVE-PORTION CAP (PRD 4.2) ==="
$tom=(Api GET "/api/menu?date=$tomorrow&size=50" $H).R|ConvertFrom-Json
$d2=@($tom.data.items|Select-Object -First 2)
"tomorrow menu has $($tom.data.total) dishes; using $($d2.Count)"
if($d2.Count -ge 2){
  $six=Api POST '/api/orders' (@{Authorization="Bearer $tok";'Idempotency-Key'=[guid]::NewGuid().ToString()}) @{items=@(@{dishId=$d2[0].dishId;quantity=3;optionIds=@()},@{dishId=$d2[1].dishId;quantity=3;optionIds=@()});deliveryDate="$tomorrow";mealSlot="Lunch";deliveryAddress="Audit Desk"}
  "3+3=6 portions -> HTTP $($six.S)  $(if($six.S -eq 400){'[PASS] rejected'}else{'[FAIL] should be rejected'})"
  "  body: $($six.R)"
  $pre6=Api POST '/api/orders/checkout-preview' $H @{items=@(@{dishId=$d2[0].dishId;quantity=3;optionIds=@()},@{dishId=$d2[1].dishId;quantity=3;optionIds=@()});deliveryDate="$tomorrow";mealSlot="Lunch"}
  "preview 3+3=6 -> HTTP $($pre6.S) $(if($pre6.S -eq 400){'[PASS] preview also blocks'}else{'[FAIL] preview allowed 6'})"
  $five=Api POST '/api/orders' (@{Authorization="Bearer $tok";'Idempotency-Key'=[guid]::NewGuid().ToString()}) @{items=@(@{dishId=$d2[0].dishId;quantity=3;optionIds=@()},@{dishId=$d2[1].dishId;quantity=2;optionIds=@()});deliveryDate="$tomorrow";mealSlot="Dinner";deliveryAddress="Audit Desk"}
  "3+2=5 portions -> HTTP $($five.S) $(if($five.S -eq 200){'[PASS] accepted (at limit)'}else{'[FAIL]'})"
  $ord=$five.R|ConvertFrom-Json
  if($five.S -eq 200){"  orderNo=$($ord.data.orderNo) total=$($ord.data.totalAmount) status=$($ord.data.status)"}
}","description":"Test cutoff auto-switch and five-portion cap live","timeoutMs":180000}

