=== Debounce / throttle (PRD A.1: button debounce) ===
import { onScopeDispose, ref, watch, type Ref } from 'vue'

/**
 * Debounces a reactive value.
 *
 * Used by the menu search box so typing does not fire a request per keystroke during the
 * 09:30-10:00 peak (PRD 3.2).
 */
export function useDebouncedRef<T>(source: Ref<T>, delayMs = 300): Ref<T> {
  const debounced = ref(source.value) as Ref<T>
  let handle: number | undefined

  watch(source, (value) => {
    if (handle !== undefined) {
      window.clearTimeout(handle)
    }
    handle = window.setTimeout(() => {
      debounced.value = value
    }, delayMs)
  })

  onScopeDispose(() => {
    if (handle !== undefined) {
      window.clearTimeout(handle)
    }

=== Pending action (double-submit guard) ===
import { ref } from 'vue'

/**
 * Single-flight guard for a button action.
 *
 * During the ordering peak employees click "Add to Cart" repeatedly (PRD 3.3). While an action
 * is in flight this rejects further invocations, so a burst of clicks produces one update and
 * one visual transition instead of jitter.
 */
export function usePendingAction(cooldownMs = 400) {
  const pending = ref(false)

  async function run<T>(action: () => T | Promise<T>): Promise<T | undefined> {
    if (pending.value) {
      return undefined
    }
    pending.value = true
    try {
      return await action()
    } finally {
      window.setTimeout(() => {
        pending.value = false
      }, cooldownMs)
    }
  }

  return { pending, run }
}

