{"command":"$base='http://localhost:8080'
function Api($m,$p,$h=@{},$b=$null){
  $pr=@{Method=$m;Uri=$base+$p;Headers=$h;UseBasicParsing=$true}
  if($b){$pr.ContentType='application/json';$pr.Body=($b|ConvertTo-Json -Depth 10 -Compress)}
  try{$r=Invoke-WebRequest @pr; return [pscustomobject]@{S=[int]$r.StatusCode;R=[string]$r.Content}}
  catch{$rp=$_.Exception.Response; if(!$rp){return [pscustomobject]@{S=0;R=$_.Exception.Message}}; $sr=New-Object IO.StreamReader($rp.GetResponseStream()); return [pscustomobject]@{S=[int]$rp.StatusCode;R=$sr.ReadToEnd()}}
}
$suf=[guid]::NewGuid().ToString('N').Substring(0,8)
$tok=((Api POST '/api/auth/register' @{} @{email="opt.$suf@example.com";password="Passw0rd123";displayName="Opt"}).R|ConvertFrom-Json).data.token
$H=@{Authorization="Bearer $tok"}
$today=(Get-Date).ToString('yyyy-MM-dd')
$tomorrow=(Get-Date).AddDays(1).ToString('yyyy-MM-dd')

# find a dish WITH required option groups on today's menu
$menu=(Api GET "/api/menu?date=$today&size=50" $H).R|ConvertFrom-Json
$target=$null
foreach($it in $menu.data.items){
  $d=(Api GET "/api/menu/dishes/$($it.dishId)" $H).R|ConvertFrom-Json
  if($d.data.optionGroups.Count -ge 2 -and ($d.data.optionGroups|Where-Object{$_.required}).Count -ge 1){ $target=$d.data; break }
}
if(-not $target){ "no dish with required groups found on today's menu"; exit }
"dish: $($target.name) base=$($target.price)"
$target.optionGroups | ForEach-Object { "  [$($_.name)] required=$($_.required) type=$($_.selectionType) -> " + (($_.options|ForEach-Object{"$($_.name)=+$($_.priceDelta) id=$($_.id)"}) -join ' ; ') }

# choose: first option of the required SINGLE group (delta usually 0) + the most expensive add-on
$picked=@()
$picked += ($target.optionGroups | Where-Object{$_.required} | Select-Object -First 1).options[0]
$addon = ($target.optionGroups | Where-Object{-not $_.required} | Select-Object -First 1)
if($addon){ $picked += ($addon.options | Sort-Object { [decimal]$_.priceDelta } -Descending)[0] }
"picked for pricing: " + (($picked|ForEach-Object{"$($_.name)(+$($_.priceDelta))"}) -join ' + ')

$expected = [decimal]$target.price + ($picked | ForEach-Object { [decimal]$_.priceDelta } | Measure-Object -Sum).Sum
"expected unit price = $expected"
$ids=@($picked|ForEach-Object{$_.id})
$body=@{items=@(@{dishId=$target.dishId;quantity=2;optionIds=$ids});deliveryDate="$tomorrow";mealSlot="Lunch"}
$pv=Api POST '/api/orders/checkout-preview' $H $body
"HTTP $($pv.S)"
$pv.R
$pj=$pv.R|ConvertFrom-Json
if($pj.data.pricedItems.Count -gt 0){
  $li=$pj.data.pricedItems[0]
  "unitPrice=$($li.unitPrice) qty=$($li.quantity) subtotal=$($li.subtotal) total=$($pj.data.total)"
  "labels: $($li.optionLabels -join ' | ')"
  if([decimal]$li.unitPrice -eq $expected){"[PASS] server-computed option pricing exact"}else{"[FAIL] expected $expected"}
  if([decimal]$li.subtotal -eq [decimal]$expected*2){"[PASS] subtotal = unit x qty exactly"}
}","description":"Verify option pricing arithmetic precisely","timeoutMs":180000}

