function Api($m,$p,$h=@{},$b=$null){
  $pr=@{Method=$m;Uri=$base+$p;Headers=$h;UseBasicParsing=$true}
  if($b){$pr.ContentType='application/json';$pr.Body=($b|ConvertTo-Json -Depth 12 -Compress)}
  try{$r=Invoke-WebRequest @pr; return [pscustomobject]@{S=[int]$r.StatusCode;R=[string]$r.Content}}
  catch{$rp=$_.Exception.Response; if(!$rp){return [pscustomobject]@{S=0;R=$_.Exception.Message}}; $sr=New-Object IO.StreamReader($rp.GetResponseStream()); return [pscustomobject]@{S=[int]$rp.StatusCode;R=$sr.ReadToEnd()}}
}
$admin=((Api POST '/api/auth/login' @{} @{email='admin@webox.com';password='Admin1234'}).R|ConvertFrom-Json).data.token
$AH=@{Authorization="Bearer $admin"}
$tomorrow=(Get-Date).AddDays(1).ToString('yyyy-MM-dd')

Write-Output "=== Restore tomorrow's daily menu (smoke test had narrowed it to 2 dishes) ==="
$all=(Api GET "/api/admin/dishes?page=0&size=200" $AH).R|ConvertFrom-Json
$avail=@($all.data.items | Where-Object { $_.available -eq $true })
"available dishes: $($avail.Count)"
$items=@($avail | ForEach-Object { @{ dishId = $_.id; totalQty = 50 } })
$put=Api PUT "/api/admin/daily-menus/$tomorrow" $AH @{ items = $items }
"PUT $tomorrow -> HTTP $($put.S)"
$rb=(Api GET "/api/admin/daily-menus/$tomorrow" $AH).R|ConvertFrom-Json
"read back: $($rb.data.items.Count) items"

$suf=[guid]::NewGuid().ToString('N').Substring(0,8)
$tok=((Api POST '/api/auth/register' @{} @{email="price.$suf@example.com";password="Passw0rd123";displayName="Price"}).R|ConvertFrom-Json).data.token
$H=@{Authorization="Bearer $tok"}
Write-Output ""
Write-Output "=== OPTION PRICING with correct optionId (Classic Beef Burger + Bacon, x2) ==="
$d=(Api GET '/api/menu/dishes/9' $H).R|ConvertFrom-Json
$base=[decimal]$d.data.price
$bun=($d.data.optionGroups|Where-Object{$_.name -eq 'Bun'}).options[0]
$sauce=($d.data.optionGroups|Where-Object{$_.name -eq 'Sauce'}).options[1]
$bacon=($d.data.optionGroups|Where-Object{$_.name -eq 'Add-ons'}).options|Where-Object{$_.name -eq 'Bacon'}
"base=$base  + $($bun.name)(+$($bun.priceDelta)) + $($sauce.name)(+$($sauce.priceDelta)) + $($bacon.name)(+$($bacon.priceDelta))"
$exp = $base + [decimal]$bun.priceDelta + [decimal]$sauce.priceDelta + [decimal]$bacon.priceDelta
"expected unit = $exp ; x2 = $($exp*2)"
$ids=@($bun.optionId,$sauce.optionId,$bacon.optionId)
$pv=Api POST '/api/orders/checkout-preview' $H @{items=@(@{dishId=9;quantity=2;optionIds=$ids});deliveryDate="$tomorrow";mealSlot="Lunch"}
$pj=$pv.R|ConvertFrom-Json
if($pj.data.pricedItems.Count -gt 0){
  $li=$pj.data.pricedItems[0]
  "unitPrice=$($li.unitPrice) qty=$($li.quantity) subtotal=$($li.subtotal) total=$($pj.data.total)"
  "labels: $($li.optionLabels -join ' | ')"
  if([decimal]$li.unitPrice -eq $exp){"[PASS] unit price exact (no float drift)"}else{"[FAIL]"}
  if([decimal]$li.subtotal -eq $exp*2){"[PASS] subtotal = unit x qty exact"}else{"[FAIL]"}
}else{ "no priced items: $($pv.R)" }

Write-Output ""
Write-Output "=== REAL-TIME PRICE UPDATE ON OPTION CHANGE (same dish, cheaper config) ==="
$ids2=@(($d.data.optionGroups|Where-Object{$_.name -eq 'Bun'}).options[0].optionId, ($d.data.optionGroups|Where-Object{$_.name -eq 'Sauce'}).options[0].optionId)
$pv2=Api POST '/api/orders/checkout-preview' $H @{items=@(@{dishId=9;quantity=2;optionIds=$ids2});deliveryDate="$tomorrow";mealSlot="Lunch"}
$pj2=$pv2.R|ConvertFrom-Json
"without Bacon: unitPrice=$($pj2.data.pricedItems[0].unitPrice) total=$($pj2.data.total)  (expect $($base*2))"
Write-Output ""
Write-Output "=== REQUIRED GROUP ENFORCEMENT (omit required Bun) ==="
$pv3=Api POST '/api/orders/checkout-preview' $H @{items=@(@{dishId=9;quantity=1;optionIds=@($bacon.optionId)});deliveryDate="$tomorrow";mealSlot="Lunch"}
"omit required Bun -> HTTP $($pv3.S)  $($pv3.R)"","description":"Restore menu and verify option pricing arithmetic","timeoutMs":180000}

