{"command":"$ErrorActionPreference='Continue'
$BU='http://localhost:8080'
function Api($m,$p,$h=@{},$b=$null){
  $pr=@{Method=$m;Uri=$BU+$p;Headers=$h;UseBasicParsing=$true}
  if($b){$pr.ContentType='application/json';$pr.Body=($b|ConvertTo-Json -Depth 12 -Compress)}
  try{$r=Invoke-WebRequest @pr; return [pscustomobject]@{S=[int]$r.StatusCode;R=[string]$r.Content}}
  catch{$rp=$_.Exception.Response; if(!$rp){return [pscustomobject]@{S=0;R=$_.Exception.Message}}; $sr=New-Object IO.StreamReader($rp.GetResponseStream()); return [pscustomobject]@{S=[int]$rp.StatusCode;R=$sr.ReadToEnd()}}
}
$admin=((Api POST '/api/auth/login' @{} @{email='admin@webox.com';password='Admin1234'}).R|ConvertFrom-Json).data.token
$AH=@{Authorization="Bearer $admin"}
$suf=[guid]::NewGuid().ToString('N').Substring(0,8)
$tok=((Api POST '/api/auth/register' @{} @{email="lang.$suf@example.com";password="Passw0rd123";displayName="Lang"}).R|ConvertFrom-Json).data.token
$EH=@{Authorization="Bearer $tok"}
$ZH='[\u4e00-\u9fff]'

Write-Output "=== SWEEP: probe error/validation responses for non-English text ==="
$probes=@(
 @{n='admin dishes size=999';      m='GET';  p='/api/admin/dishes?page=0&size=999';        h=$AH; b=$null}
 @{n='admin dishes page=-1';       m='GET';  p='/api/admin/dishes?page=-1&size=10';        h=$AH; b=$null}
 @{n='orders size=999';            m='GET';  p='/api/orders?page=0&size=999';             h=$EH; b=$null}
 @{n='menu size=999';              m='GET';  p="/api/menu?date=$(Get-Date -Format yyyy-MM-dd)&size=999"; h=$EH; b=$null}
 @{n='admin dish create: missing name'; m='POST'; p='/api/admin/dishes'; h=$AH; b=@{description='x';price='1.00';category='Chinese';spiceLevel='None'}}
 @{n='admin dish create: blank name';   m='POST'; p='/api/admin/dishes'; h=$AH; b=@{name='';description='x';price='1.00';category='Chinese';spiceLevel='None'}}
 @{n='admin dish create: bad price';    m='POST'; p='/api/admin/dishes'; h=$AH; b=@{name='X';description='x';price='-5';category='Chinese';spiceLevel='None'}}
 @{n='admin dish create: bad enum';     m='POST'; p='/api/admin/dishes'; h=$AH; b=@{name='X';description='x';price='5';category='Nope';spiceLevel='None'}}
 @{n='register: no email';         m='POST'; p='/api/auth/register'; h=@{}; b=@{password='Passw0rd123';displayName='x'}}
 @{n='register: bad email';        m='POST'; p='/api/auth/register'; h=@{}; b=@{email='not-an-email';password='Passw0rd123';displayName='x'}}
 @{n='register: long email';       m='POST'; p='/api/auth/register'; h=@{}; b=@{email=('a'*250+'@x.com');password='Passw0rd123';displayName='x'}}
 @{n='login: null body';           m='POST'; p='/api/auth/login'; h=@{}; b=@{email=$null;password=$null}}
 @{n='prefs: bad enum';            m='PUT';  p='/api/users/me/preferences'; h=$EH; b=@{spicePreference='Nope'}}
 @{n='prefs: bad budget';          m='PUT';  p='/api/users/me/preferences'; h=$EH; b=@{budgetMin='abc'}}
 @{n='prefs: negative budget';     m='PUT';  p='/api/users/me/preferences'; h=$EH; b=@{budgetMin='-1.00'}}
 @{n='order: empty items';         m='POST'; p='/api/orders'; h=@{Authorization="Bearer $tok";'Idempotency-Key'=[guid]::NewGuid().ToString()}; b=@{items=@();deliveryDate='2026-10-18';mealSlot='Lunch';deliveryAddress='x'}}
 @{n='order: bad mealSlot';        m='POST'; p='/api/orders'; h=@{Authorization="Bearer $tok";'Idempotency-Key'=[guid]::NewGuid().ToString()}; b=@{items=@(@{dishId=1;quantity=1;optionIds=@()});deliveryDate='2026-10-18';mealSlot='Brunch';deliveryAddress='x'}}
 @{n='order: long address';        m='POST'; p='/api/orders'; h=@{Authorization="Bearer $tok";'Idempotency-Key'=[guid]::NewGuid().ToString()}; b=@{items=@(@{dishId=1;quantity=1;optionIds=@()});deliveryDate='2026-10-18';mealSlot='Lunch';deliveryAddress=('x'*300)}}
 @{n='daily-menu: empty items';    m='PUT';  p='/api/admin/daily-menus/2026-10-19'; h=$AH; b=@{items=@()}}
 @{n='daily-menu: neg qty';        m='PUT';  p='/api/admin/daily-menus/2026-10-19'; h=$AH; b=@{items=@(@{dishId=1;totalQty=-5})}}
 @{n='bad JSON body';              m='POST'; p='/api/auth/login'; h=@{}; b=$null}
)
$bad=@()
foreach($pr in $probes){
  $r = if($pr.p -eq '/api/auth/login' -and $pr.n -eq 'bad JSON body'){ Api $pr.m $pr.p $pr.h } else { Api $pr.m $pr.p $pr.h $pr.b }
  $hit = $r.R -match $ZH
  $flag = if($hit){'<-- NON-ENGLISH'}else{''}
  "{0,-34} HTTP {1,-4} {2}" -f $pr.n,$r.S,$flag
  if($hit){ $bad += [pscustomobject]@{Probe=$pr.n;Status=$r.S;Body=$r.R} }
}
Write-Output ""
Write-Output "=== VIOLATIONS FOUND: $($bad.Count) ==="
$bad | ForEach-Object { "[$($_.Probe)] HTTP $($_.Status)`n  $($_.Body)" }","description":"Sweep API error responses for non-English messages","timeoutMs":240000}

