{"file_path":"C:\Users\liujibiao\AppData\Local\Temp\webox-ui\drive.mjs","content":"// UI end-to-end driver for WeBox SPA, over Chrome DevTools Protocol.
// Uses Node's built-in fetch + WebSocket (Node 22+/24). No external deps.
const CDP = process.env.CDP || 'http://127.0.0.1:9333';
const APP = process.env.APP || 'http://localhost:5173';

const results = [];
function check(name, ok, detail = '') {
  results.push({ name, ok: !!ok, detail });
  console.log(`${ok ? '[PASS]' : '[FAIL]'} ${name}${detail ? '  -- ' + detail : ''}`);
}

// ---- minimal CDP client ----
class Session {
  constructor(ws) { this.ws = ws; this.id = 0; this.pending = new Map(); }
  static async attach(wsUrl) {
    const ws = new WebSocket(wsUrl);
    await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });
    const s = new Session(ws);
    ws.onmessage = (ev) => {
      const msg = JSON.parse(ev.data);
      if (msg.id && s.pending.has(msg.id)) {
        const { resolve, reject } = s.pending.get(msg.id);
        s.pending.delete(msg.id);
        msg.error ? reject(new Error(JSON.stringify(msg.error))) : resolve(msg.result);
      }
    };
    return s;
  }
  send(method, params = {}) {
    const id = ++this.id;
    return new Promise((resolve, reject) => {
      this.pending.set(id, { resolve, reject });
      this.ws.send(JSON.stringify({ id, method, params }));
      setTimeout(() => {
        if (this.pending.has(id)) { this.pending.delete(id); reject(new Error('timeout ' + method)); }
      }, 30000);
    });
  }
  async eval(expression) {
    const r = await this.send('Runtime.evaluate', {
      expression: `(async()=>{${expression}})()`,
      awaitPromise: true, returnByValue: true,
    });
    if (r.exceptionDetails) throw new Error(r.exceptionDetails.exception?.description || 'eval error');
    return r.result.value;
  }
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function waitFor(s, expr, timeoutMs = 15000, label = expr) {
  const t0 = Date.now();
  while (Date.now() - t0 < timeoutMs) {
    try { if (await s.eval(`return !!(${expr})`)) return true; } catch { }
    await sleep(200);
  }
  return false;
}

const text = `document.body.innerText`;

(async () => {
  const targets = await (await fetch(CDP + '/json')).json();
  const page = targets.find((t) => t.type === 'page');
  if (!page) throw new Error('no page target');
  const s = await Session.attach(page.webSocketDebuggerUrl);
  await s.send('Page.enable');
  await s.send('Runtime.enable');
  await s.send('Network.enable');

  // collect console errors
  const consoleErrors = [];
  s.ws.addEventListener('message', (ev) => {
    const m = JSON.parse(ev.data);
    if (m.method === 'Runtime.consoleAPICalled' && m.params.type === 'error') {
      consoleErrors.push((m.params.args || []).map((a) => a.value || a.description).join(' '));
    }
  });

  const suffix = Math.random().toString(16).slice(2, 10);
  const email = `ui.${suffix}@example.com`;
  const password = 'Passw0rd123';

  // ---------- 1. Register ----------
  console.log('\n== UI: registration ==');
  await s.eval(`location.href='${APP}/register'`);
  await waitFor(s, `document.querySelector('#register-email')`, 20000, 'register form');
  check('register page renders', await s.eval(`return !!document.querySelector('#register-email')`));

  await s.eval(`
    const set=(sel,v)=>{const el=document.querySelector(sel);
      const proto=Object.getPrototypeOf(el); const d=Object.getOwnPropertyDescriptor(proto,'value');
      d.set.call(el,v); el.dispatchEvent(new Event('input',{bubbles:true})); el.dispatchEvent(new Event('change',{bubbles:true}));};
    set('#register-email','${email}');
    set('#register-name','UI Auditor');
    set('#register-password','${password}');
    const c=document.querySelector('#register-confirm'); if(c) set('#register-confirm','${password}');
    return true;
  `);
  await sleep(300);
  await s.eval(`document.querySelector('form').requestSubmit(); return true;`);
  const registered = await waitFor(s, `location.pathname==='/menu' || /menu/i.test(location.pathname)`, 20000, 'redirect to menu');
  check('registration redirects to menu', registered, 'path=' + await s.eval(`return location.pathname`));
  check('session persists in storage', await s.eval(`return !!(localStorage.getItem('webox.auth')||localStorage.getItem('webox.token')||Object.keys(localStorage).length>0)`),
    'keys=' + await s.eval(`return Object.keys(localStorage).join(',')`));

  // ---------- 2. Menu ----------
  console.log('\n== UI: menu browsing ==');
  await waitFor(s, `document.querySelectorAll('article,.wb-card,[data-dish]').length>0 || document.body.innerText.length>200`, 15000);
  const menuText = await s.eval(`return ${text}`);
  const cards = await s.eval(`return document.querySelectorAll('article').length`);
  check('menu renders dish cards', cards > 0, 'article count=' + cards);
  check('menu is English-only', !/[\u4e00-\u9fff]/.test(menuText));
  check('menu shows a price with 2 decimals', /¥\s?\d+\.\d{2}/.test(menuText), (menuText.match(/¥\s?\d+\.\d{2}/) || [''])[0]);

  // search
  const searchSel = await s.eval(`
    const el=document.querySelector('input[type=search],input[placeholder*="earch"],input[placeholder*="ish"]');
    if(!el) return ''; el.id?('#'+el.id):(el.name?('[name="'+el.name+'"]'):'input[type=search]');
  `);
  if (searchSel) {
    await s.eval(`
      const el=document.querySelector('${searchSel}');
      const d=Object.getOwnPropertyDescriptor(Object.getPrototypeOf(el),'value');
      d.set.call(el,'chicken'); el.dispatchEvent(new Event('input',{bubbles:true}));
      return true;`);
    await sleep(1200);
    const names = await s.eval(`return [...document.querySelectorAll('article h3, article h2, article .font-semibold')].map(e=>e.innerText).join(' | ')`);
    check('search narrows the list', (await s.eval(`return document.querySelectorAll('article').length`)) > 0, names.slice(0, 90));
  } else {
    check('search input found', false, 'no search box located');
  }

  // ---------- 3. Dish detail ----------
  console.log('\n== UI: dish detail ==');
  await s.eval(`history.pushState({},'','/menu'); location.href='${APP}/menu'; return true;`);
  await waitFor(s, `document.querySelectorAll('article').length>0`, 15000);
  // find a dish with options by visiting detail pages
  let detailOk = false, optCount = 0;
  const ids = await s.eval(`
    const links=[...document.querySelectorAll('a[href*="/menu/"], a[href*="/dishes/"]')].map(a=>a.getAttribute('href'));
    return JSON.stringify(links.slice(0,12));`);
  const hrefs = JSON.parse(ids || '[]');
  for (const href of hrefs) {
    await s.eval(`location.href='${APP}'+${JSON.stringify(href)}`);
    await sleep(900);
    const n = await s.eval(`return document.querySelectorAll('input[type=radio],input[type=checkbox],select').length`);
    if (n > 0) { detailOk = true; optCount = n; break; }
  }
  check('dish detail page reachable', hrefs.length > 0, `links=${hrefs.length}`);
  check('dish options are interactive', detailOk, `controls=${optCount}`);

  // ---------- 4. Cart ----------
  console.log('\n== UI: cart ==');
  await s.eval(`location.href='${APP}/menu'`); await waitFor(s, `document.querySelectorAll('article').length>0`, 15000);
  const added = await s.eval(`
    const btns=[...document.querySelectorAll('button')].filter(b=>/add/i.test(b.innerText));
    if(!btns.length) return false; btns[0].click(); return true;`);
  check('add-to-cart button present on card', added);
  await sleep(1200);
  await s.eval(`location.href='${APP}/cart'`);
  await waitFor(s, `document.body.innerText.length>100`, 12000);
  const cartText = await s.eval(`return ${text}`);
  check('cart page lists the item', /cart/i.test(cartText) && /¥\s?\d+\.\d{2}/.test(cartText));
  check('cart shows the 5-item limit', /\/\s*5|5\s*items|at most 5/i.test(cartText), (cartText.match(/.{0,24}at most 5.{0,24}/i) || [''])[0]);
  check('cart is English-only', !/[\u4e00-\u9fff]/.test(cartText));

  // ---------- 5. Preferences ----------
  console.log('\n== UI: preferences ==');
  await s.eval(`location.href='${APP}/settings/preferences'`);
  await sleep(1500);
  let prefText = await s.eval(`return ${text}`);
  if (!/preference|allergen/i.test(prefText)) {
