    return JSON.stringify(links.slice(0,12));`);
  const hrefs = JSON.parse(ids || '[]');
  for (const href of hrefs) {
    await s.eval(`location.href='${APP}'+${JSON.stringify(href)}`);
    await sleep(900);
    const n = await s.eval(`return document.querySelectorAll('input[type=radio],input[type=checkbox],select').length`);
    if (n > 0) { detailOk = true; optCount = n; break; }
  }
  check('dish detail page reachable', hrefs.length > 0, `links=${hrefs.length}`);
  check('dish options are interactive', detailOk, `controls=${optCount}`);

  // ---------- 4. Cart ----------
  console.log('\n== UI: cart ==');
  await s.eval(`location.href='${APP}/menu'`); await waitFor(s, `document.querySelectorAll('article').length>0`, 15000);
  const added = await s.eval(`
    const btns=[...document.querySelectorAll('button')].filter(b=>/add/i.test(b.innerText));
    if(!btns.length) return false; btns[0].click(); return true;`);
  check('add-to-cart button present on card', added);
  await sleep(1200);
  await s.eval(`location.href='${APP}/cart'`);
  await waitFor(s, `document.body.innerText.length>100`, 12000);
  const cartText = await s.eval(`return ${text}`);
  check('cart page lists the item', /cart/i.test(cartText) && /¥\s?\d+\.\d{2}/.test(cartText));
  check('cart shows the 5-item limit', /\/\s*5|5\s*items|at most 5/i.test(cartText), (cartText.match(/.{0,24}at most 5.{0,24}/i) || [''])[0]);
  check('cart is English-only', !/[\u4e00-\u9fff]/.test(cartText));

  // ---------- 5. Preferences ----------
  console.log('\n== UI: preferences ==');
  await s.eval(`location.href='${APP}/settings/preferences'`);
  await sleep(1500);
  let prefText = await s.eval(`return ${text}`);
  if (!/preference|allergen/i.test(prefText)) {
    await s.eval(`location.href='${APP}/preferences'`); await sleep(1500);
    prefText = await s.eval(`return ${text}`);
  }
  check('preferences page renders allergen controls', /allergen/i.test(prefText), prefText.split('\n').slice(0, 4).join(' / '));
  check('preferences is English-only', !/[\u4e00-\u9fff]/.test(prefText));

  // ---------- 6. Orders ----------
  console.log('\n== UI: orders ==');
  await s.eval(`location.href='${APP}/orders'`); await sleep(1800);
  const ordersText = await s.eval(`return ${text}`);
  check('orders page renders', /order/i.test(ordersText), ordersText.split('\n').slice(0, 3).join(' / '));

  // ---------- 7. Authorization boundary ----------
  console.log('\n== UI: authorization ==');
  await s.eval(`location.href='${APP}/console/dishes'`); await sleep(1800);
  const p = await s.eval(`return location.pathname`);
  const consText = await s.eval(`return ${text}`);
  check('employee is kept out of Console', !/Console/i.test(consText) || p !== '/console/dishes', 'path=' + p);
  await s.eval(`location.href='${APP}/not-a-real-page'`); await sleep(1200);
  const nf = await s.eval(`return ${text}`);
  check('404 route renders an English not-found page', /not found|404|doesn.t exist/i.test(nf), nf.split('\n')[0]);

  // ---------- 8. Responsive ----------
  console.log('\n== UI: responsive ==');
  await s.send('Emulation.setDeviceMetricsOverride', { width: 375, height: 812, deviceScaleFactor: 2, mobile: true });
  await s.eval(`location.href='${APP}/menu'`);
  await waitFor(s, `document.querySelectorAll('article').length>0`, 15000);
  const narrow = await s.eval(`return {w:innerWidth, cols:getComputedStyle(document.querySelector('article').parentElement).gridTemplateColumns.split(' ').length}`);
  check('mobile viewport (375px) renders menu', narrow.w === 375 && narrow.cols >= 1, JSON.stringify(narrow));
  const overflow = await s.eval(`return document.documentElement.scrollWidth > window.innerWidth + 2`);
  check('no horizontal overflow on mobile', !overflow);
  await s.send('Page.captureScreenshot', {}).then(async (r) => {
    const fs = await import('node:fs');
    fs.writeFileSync(process.env.SHOT_DIR + '\\mobile-menu.png', Buffer.from(r.data, 'base64'));
  });
  await s.send('Emulation.clearDeviceMetricsOverride');

  // ---------- 9. Admin console ----------
  console.log('\n== UI: Console (admin) ==');
  await s.eval(`
    Object.keys(localStorage).filter(k=>/webox|auth|token/i.test(k)).forEach(k=>localStorage.removeItem(k));
    location.href='${APP}/login'; return true;`);
  await sleep(1500);
  await s.eval(`
    const set=(sel,v)=>{const el=document.querySelector(sel);
      const d=Object.getOwnPropertyDescriptor(Object.getPrototypeOf(el),'value');
      d.set.call(el,v); el.dispatchEvent(new Event('input',{bubbles:true}));};
    set('#login-email','admin@webox.com'); set('#login-password','Admin1234');
    document.querySelector('form').requestSubmit(); return true;`);
  const adminIn = await waitFor(s, `/console|menu/i.test(location.pathname)`, 20000);
  check('admin can sign in via UI', adminIn, 'path=' + await s.eval(`return location.pathname`));
  await s.eval(`location.href='${APP}/console/dishes'`); await sleep(2500);
  const adminText = await s.eval(`return ${text}`);
  check('Console dish table renders', /dish/i.test(adminText) && (await s.eval(`return document.querySelectorAll('table,tbody tr').length`)) > 0,
    'rows=' + await s.eval(`return document.querySelectorAll('tbody tr').length`));
  check('Console is English-only', !/[\u4e00-\u9fff]/.test(adminText));

  // ---------- 10. Console errors ----------
  console.log('\n== browser console errors ==');
  const realErrors = consoleErrors.filter((e) => !/favicon|DevTools/i.test(e));
  check('no uncaught console errors', realErrors.length === 0, realErrors.slice(0, 3).join(' || '));

  // ---------- summary ----------
  const failed = results.filter((r) => !r.ok);
  console.log('\n' + '='.repeat(60));
  console.log(`UI CHECKS: ${results.length - failed.length}/${results.length} passed`);
  if (failed.length) { console.log('FAILURES:'); failed.forEach((f) => console.log(' - ' + f.name + ' :: ' + f.detail)); }
  process.exit(failed.length ? 1 : 0);
})().catch((e) => { console.error('DRIVER ERROR:', e.message); process.exit(2); });
"}

