  const addClicks = await s.eval(`
    const btns=[...document.querySelectorAll('article button.wb-btn-primary')].filter(b=>!b.disabled);
    if(!btns.length) return 0; btns[0].click(); return 1;`);
  check('add to cart works from a card', addClicks === 1);
  await sleep(1500);
  await go('/cart');
  await sleep(1200);
  const cartText = await s.eval(`return document.body.innerText`);
  check('cart lists the added item', /Cart/i.test(cartText) && /¥\s?\d+\.\d{2}/.test(cartText), cartText.split('\n').slice(0, 3).join(' / '));
  check('cart shows the total', /Total/i.test(cartText));
  check('cart shows the 5-item cap', /5/.test(cartText) && /at most 5/i.test(cartText), (cartText.match(/[^\n]*at most 5[^\n]*/i) || [''])[0]);
  check('cart page is English-only', !/[\u4e00-\u9fff]/.test(cartText));
  await shot('03-cart');

  // ---------- 5. Checkout ----------
  console.log('\n== UI: checkout ==');
  await s.eval(`${byText('Proceed to Checkout')} ? ${byText('Proceed to Checkout')}.click() : ${byText('Checkout')}.click(); return true;`);
  await sleep(1800);
  if (!/checkout/i.test(await s.eval(`return location.pathname`))) { await go('/checkout'); await sleep(1500); }
  const coText = await s.eval(`return document.body.innerText`);
  check('checkout page renders order summary', /Checkout|Place Order/i.test(coText), coText.split('\n').slice(0, 4).join(' / '));
  check('checkout offers Lunch/Dinner meal slot', /Lunch/.test(coText) && /Dinner/.test(coText));
  check('checkout shows the resolved (auto-switched) meal', /auto|switched|adjusted/i.test(coText) || /Lunch|Dinner/.test(coText));
  check('checkout has a delivery address field', await s.eval(`return !!document.querySelector('input[type=text],textarea')`));
  check('checkout is English-only', !/[\u4e00-\u9fff]/.test(coText));
  await shot('04-checkout');

  // place the order
  const placed = await s.eval(`
    const set=(sel,v)=>{const el=document.querySelector(sel); if(!el) return false;
      const d=Object.getOwnPropertyDescriptor(Object.getPrototypeOf(el),'value');
      d.set.call(el,v); el.dispatchEvent(new Event('input',{bubbles:true})); el.dispatchEvent(new Event('change',{bubbles:true})); return true;};
    const ta=document.querySelector('textarea'); const ti=[...document.querySelectorAll('input[type=text]')].find(i=>!i.readOnly);
    if(ta) set('textarea','Building A, Desk 101'); else if(ti) set('input[type=text]','Building A, Desk 101');
    const b=[...document.querySelectorAll('button')].find(e=>/Place Order/i.test(e.innerText));
    if(!b) return 'no-button'; if(b.disabled) return 'disabled'; b.click(); return 'clicked';`);
  check('Place Order button is actionable', placed === 'clicked', placed);
  const success = await waitFor(s, `/order-success/.test(location.pathname) || /Order (placed|confirmed|success)/i.test(document.body.innerText)`, 20000);
  check('order is placed and success page shown', success, 'path=' + await s.eval(`return location.pathname`));
  const sucText = await s.eval(`return document.body.innerText`);
  check('success page shows an order number', /WB\d{8}-\d+/.test(sucText), (sucText.match(/WB\d{8}-\d+/) || [''])[0]);
  check('success page shows delivery info', /Delivery|Address|Lunch|Dinner/i.test(sucText));
  await shot('05-order-success');

  // ---------- 6. Duplicate-submit guard ----------
  console.log('\n== UI: repeat-order guard ==');
  await go('/checkout'); await sleep(1800);
  const co2 = await s.eval(`return document.body.innerText`);
  const viewExisting = await s.eval(`return [...document.querySelectorAll('button,a')].some(e=>/View Existing Order/i.test(e.innerText))`);
  check('already-ordered meal shows "View Existing Order"', viewExisting, co2.split('\n').filter((l) => /Existing|already/i.test(l)).join(' / '));

  // ---------- 7. Orders ----------
  console.log('\n== UI: my orders ==');
  await go('/orders'); await sleep(1500);
  const ordText = await s.eval(`return document.body.innerText`);
  check('order list renders the order', /WB\d{8}-\d+/.test(ordText), (ordText.match(/WB\d{8}-\d+/) || [''])[0]);
  check('order list is English-only', !/[\u4e00-\u9fff]/.test(ordText));
  await shot('06-orders');

  // ---------- 8. Preferences ----------
  console.log('\n== UI: preferences ==');
  await go('/settings'); await sleep(1600);
  const prefText = await s.eval(`return document.body.innerText`);
  check('preferences page has allergen toggles', /Allergen/i.test(prefText));
  check('preferences offers the 7 canonical allergens',
    ['Peanuts', 'Dairy', 'Egg', 'Gluten', 'Soy', 'Fish', 'Shellfish'].every((a) => prefText.includes(a)));
  check('preferences expose spice + taste + budget', /Spice/i.test(prefText) && /Taste|Flavour|Flavor/i.test(prefText) && /Budget/i.test(prefText));
  check('preferences is English-only', !/[\u4e00-\u9fff]/.test(prefText));
  await shot('07-preferences');

  // ---------- 9. Authorization + 404 ----------
  console.log('\n== UI: authorization ==');
  await go('/console/dishes'); await sleep(1500);
  check('employee is redirected away from Console', (await s.eval(`return location.pathname`)) !== '/console/dishes',
    'path=' + await s.eval(`return location.pathname`));
  await go('/nope'); await sleep(1000);
  check('unknown route shows English 404', /not found/i.test(await s.eval(`return document.body.innerText`)));

  // ---------- 10. Responsive ----------
  console.log('\n== UI: responsive (mobile) ==');
  await s.send('Emulation.setDeviceMetricsOverride', { width: 375, height: 812, deviceScaleFactor: 2, mobile: true });
  await go('/'); await waitFor(s, `document.querySelectorAll('article').length>0`, 20000);
  const metrics = await s.eval(`
    const a=document.querySelector('article'); if(!a) return null;
    const grid=a.parentElement;
    const cols=getComputedStyle(grid).gridTemplateColumns.split(' ').filter(Boolean).length;
    return {w:innerWidth, cols, overflow: document.documentElement.scrollWidth>window.innerWidth+2};`);
  check('mobile 375px viewport renders the menu', !!metrics && metrics.w === 375, JSON.stringify(metrics));
  check('no horizontal overflow at 375px', metrics && !metrics.overflow, JSON.stringify(metrics));
  await shot('08-menu-mobile');
  await s.send('Emulation.clearDeviceMetricsOverride');

  // ---------- 11. Admin Console ----------
  console.log('\n== UI: Console (admin) ==');
  await s.eval(`localStorage.clear(); location.href='${APP}/login'; return true;`); await sleep(1500);
  await s.eval(`${SET} set('#login-email','admin@webox.com'); set('#login-password','Admin1234');
    document.querySelector('form').requestSubmit(); return true;`);
  const adminIn = await waitFor(s, `location.pathname.startsWith('/console')`, 20000);
  check('admin sign-in lands in Console', adminIn, 'path=' + await s.eval(`return location.pathname`));
  await sleep(2000);
  const rows = await s.eval(`return document.querySelectorAll('tbody tr').length`);
  const adminText = await s.eval(`return document.body.innerText`);
  check('Console dish table renders rows', rows > 0, 'rows=' + rows);
  check('Console has search + category filter', /Search/i.test(adminText) && /Categor|Cuisine/i.test(adminText));
  check('Console offers New Dish', /New Dish|Add Dish/i.test(adminText));
  check('Console is English-only', !/[\u4e00-\u9fff]/.test(adminText));
  await shot('09-console-dishes');

  await go('/console/daily-menu'); await sleep(2000);
  const dmText = await s.eval(`return document.body.innerText`);
  check('Console daily-menu page renders', /Daily Menu/i.test(dmText) && /quantit|qty|supply/i.test(dmText), dmText.split('\n').slice(0, 3).join(' / '));
  check('daily-menu page is English-only', !/[\u4e00-\u9fff]/.test(dmText));
  await shot('10-console-daily-menu');

  // ---------- 12. Console errors ----------
  const realErrors = consoleErrors.filter((e) => !/favicon|DevTools|404 \(Not Found\)/i.test(e));
  check('no uncaught browser console errors', realErrors.length === 0, realErrors.slice(0, 3).join(' || '));

  const failed = results.filter((r) => !r.ok);
  console.log('\n' + '='.repeat(64));
  console.log(`UI CHECKS: ${results.length - failed.length}/${results.length} passed`);
  if (failed.length) { console.log('FAILURES:'); failed.forEach((f) => console.log('  - ' + f.name + ' :: ' + f.detail)); }
  process.exit(failed.length ? 1 : 0);
})().catch((e) => { console.error('DRIVER ERROR:', e.message); process.exit(2); });

