  check('menu shows multiple cuisines before filtering', allCats.length > 0, allCats);
  const btns = await s.eval(`return JSON.stringify([...document.querySelectorAll('button')].map(b=>b.innerText.trim()).filter(Boolean))`);
  console.log('   buttons on menu:', btns.slice(0, 300));
  const clicked = await s.eval(`const b=${byText('Chinese')}; if(!b) return 'not-found'; b.click(); return 'clicked';`);
  await sleep(1800);
  const afterCn = await s.eval(`return {count: document.querySelectorAll('article').length, cats: [...new Set([...document.querySelectorAll('article .wb-chip')].map(e=>e.innerText.trim()))].join(',')}`);
  check('single cuisine filter narrows to that cuisine', clicked === 'clicked' && afterCn.count > 0 && /Chinese/.test(afterCn.cats) && !/Japanese|Western|Korean/.test(afterCn.cats), `${clicked} -> ${JSON.stringify(afterCn)}`);
  const clicked2 = await s.eval(`const b=${byText('Japanese')}; if(!b) return 'not-found'; b.click(); return 'clicked';`);
  await sleep(1800);
  const after2 = await s.eval(`return {count: document.querySelectorAll('article').length, cats: [...new Set([...document.querySelectorAll('article .wb-chip')].map(e=>e.innerText.trim()))].join(',')}`);
  check('multi-select shows Chinese + Japanese together', clicked2 === 'clicked' && /Chinese/.test(after2.cats) && /Japanese/.test(after2.cats), JSON.stringify(after2));
  await shot('11-cuisine-filter');

  // ---------- cart cap ----------
  console.log('\n== cart cap counter ==');
  await go('/');
  await waitFor(`document.querySelectorAll('article').length>0`, 20000);
  // add 5 portions of the first dish (should hit the cap exactly)
  await s.eval(`
    const cards=[...document.querySelectorAll('article')];
    for(let i=0;i<5;i++){ const b=cards[0].querySelector('button.wb-btn-primary'); if(b&&!b.disabled) b.click(); }
    return true;`);
  await sleep(2000);
  await go('/cart');
  await sleep(1500);
  const cartText = await s.eval(`return document.body.innerText`);
  check('cart counter shows "n / 5 items"', /\d\s*\/\s*5\s*items/.test(cartText), (cartText.match(/\d\s*\/\s*5\s*items/) || [''])[0]);
  check('cap explanation appears once the limit is reached', /at most 5/i.test(cartText), (cartText.match(/[^\n]*at most 5[^\n]*/i) || [''])[0]);
  const disabledPlus = await s.eval(`return [...document.querySelectorAll('button')].filter(b=>b.disabled && /at most 5/i.test(b.title||'')).length`);
  check('"+" button is disabled at the cap with a reason tooltip', disabledPlus > 0, 'disabled-with-reason=' + disabledPlus);
  await shot('12-cart-at-cap');

  // ---------- checkout ----------
  console.log('\n== checkout end-to-end ==');
  await go('/checkout', 2000);
  const addrSel = await s.eval(`const i=document.querySelector('#address');
    return i? 'found type=' + (i.getAttribute('type')||'(default text)') + ' placeholder=' + i.placeholder : 'missing'`);
  check('checkout has a dedicated #address input', /^found/.test(addrSel), addrSel);
  const beforeDisabled = await s.eval(`const b=${byText('Place Order')}; return b? b.disabled : null`);
  check('Place Order is disabled while the address is empty', beforeDisabled === true, 'disabled=' + beforeDisabled);
  await s.eval(`${SET} set('#address','Building A, Desk 101'); return true;`);
  await sleep(1800);
  const afterDisabled = await s.eval(`const b=${byText('Place Order')}; return b? b.disabled : null`);
  check('Place Order enables once a valid address is entered', afterDisabled === false, 'disabled=' + afterDisabled);
  await shot('13-checkout-filled');

  const placed = await s.eval(`const b=${byText('Place Order')}; if(!b) return 'missing'; b.click(); return 'clicked';`);
  const ok = await waitFor(`/order-success/.test(location.pathname)`, 25000);
  check('order submits and routes to the success page', ok, 'clicked=' + placed + ' path=' + await s.eval(`return location.pathname`));
  const sucText = await s.eval(`return document.body.innerText`);
  check('success page shows an order number', /WB\d{8}-\d+/.test(sucText), (sucText.match(/WB\d{8}-\d+/) || [''])[0]);
  check('success page shows delivery date + slot + address', /Lunch|Dinner/.test(sucText) && /Building A/i.test(sucText));
  await shot('14-order-success');

  // ---------- repeat-order guard ----------
  console.log('\n== repeat-order guard ==');
  await go('/checkout', 2200);
  const veo = await s.eval(`return [...document.querySelectorAll('button,a')].some(e=>/View Existing Order/i.test(e.innerText))`);
  check('same meal now offers "View Existing Order"', veo);
  await shot('15-view-existing-order');

  // ---------- orders list ----------
  console.log('\n== orders list ==');
  await go('/orders', 2000);
  const ordText = await s.eval(`return document.body.innerText`);
  check('order list shows the placed order number', /WB\d{8}-\d+/.test(ordText), (ordText.match(/WB\d{8}-\d+/) || [''])[0]);
  check('order list shows the Pending status', /Pending/i.test(ordText));

  // ---------- Console search/filter ----------
  console.log('\n== Console search + filter ==');
  await s.eval(`localStorage.clear(); location.href='${APP}/login'; return true;`); await sleep(1800);
  await s.eval(`${SET} set('#login-email','admin@webox.com'); set('#login-password','Admin1234'); document.querySelector('form').requestSubmit(); return true;`);
  await waitFor(`location.pathname.startsWith('/console')`, 20000);
  await sleep(2200);
  const ctl = await s.eval(`return {
    search: !!document.querySelector('input[aria-label="Search dishes"]'),
