    category: !!document.querySelector('select[aria-label="Category"]'),
    categoryOpts: [...(document.querySelector('select[aria-label="Category"]')?.options||[])].map(o=>o.text).join(','),
    status: !!document.querySelector('select[aria-label="Status"]'),
    rows: document.querySelectorAll('tbody tr').length }`);
  check('Console has a working search box', ctl.search, JSON.stringify(ctl));
  check('Console has a category filter with all cuisines', ctl.category && /Chinese/.test(ctl.categoryOpts) && /Japanese/.test(ctl.categoryOpts), ctl.categoryOpts);
  check('Console has a status filter', ctl.status);
  // exercise the console search
  await s.eval(`${SET} set('input[aria-label="Search dishes"]','burger'); return true;`);
  await sleep(1800);
  const searched = await s.eval(`return {rows: document.querySelectorAll('tbody tr').length, first: (document.querySelector('tbody tr')?.innerText||'').slice(0,40)}`);
  check('Console search filters the table', searched.rows > 0 && searched.rows < ctl.rows, JSON.stringify(searched));
  await shot('16-console-search');
  // exercise the category filter
  await s.eval(`${SET} set('input[aria-label="Search dishes"]',''); return true;`); await sleep(1200);
  await s.eval(`const sel=document.querySelector('select[aria-label="Category"]');
    const d=Object.getOwnPropertyDescriptor(Object.getPrototypeOf(sel),'value');
    d.set.call(sel,'Japanese'); sel.dispatchEvent(new Event('change',{bubbles:true})); return true;`);
  await sleep(1800);
  const filtered = await s.eval(`return {rows: document.querySelectorAll('tbody tr').length, cats: [...new Set([...document.querySelectorAll('tbody tr')].map(r=>r.children[3]?.innerText||''))].join(',')}`);
  check('Console category filter narrows the table', filtered.rows > 0, JSON.stringify(filtered));

  const failed = results.filter((r) => !r.ok);
  console.log('\n' + '='.repeat(64));
  console.log(`FOCUSED UI CHECKS: ${results.length - failed.length}/${results.length} passed`);
  if (failed.length) { console.log('FAILURES:'); failed.forEach((f) => console.log('  - ' + f.n + ' :: ' + f.d)); }
  process.exit(failed.length ? 1 : 0);
})().catch((e) => { console.error('DRIVER ERROR:', e.message); process.exit(2); });
