      if (m.method === 'Network.requestWillBeSent') s.reqs.push({ id: m.params.requestId, url: m.params.request.url, method: m.params.request.method });
      if (m.method === 'Network.responseReceived') { const r = s.resps.get(m.params.requestId) || {}; r.status = m.params.response.status; s.resps.set(m.params.requestId, r); }
      if (m.method === 'Network.loadingFinished') { /* noop */ }
    };
    return s;
  }
  send(method, params = {}) { const id = ++this.id; return new Promise((res, rej) => { this.p.set(id, { resolve: res, reject: rej }); this.ws.send(JSON.stringify({ id, method, params })); setTimeout(() => { if (this.p.has(id)) { this.p.delete(id); rej(new Error('timeout ' + method)); } }, 30000); }); }
