  s.reqs = []; s.resps = new Map();
  await s.eval(`const b=${byText('Chinese')}; b.click(); return true;`);
  await sleep(2500);
  const calls = s.apiCalls().filter((c) => /\/api\/menu\?/.test(c.url));
  console.log('   captured menu calls:');
  for (const c of calls) { const st = s.resps.get(c.id)?.status; console.log(`     ${st} ${c.url}`); }
  const last = calls[calls.length - 1];
  let bodySnippet = '';
  if (last) { const b = await s.body(last.id); bodySnippet = (b || '').slice(0, 200); console.log('     body:', bodySnippet); }
  const count = await s.eval(`return document.querySelectorAll('article').length`);
  check('cuisine filter returns dishes', count > 0, `before=${base} after=${count}`);

  // Direct-API control: same request the UI sent, replayed with curl-like fetch
  if (last) {
    const ctrl = await s.eval(`
      const token = JSON.parse(localStorage.getItem('webox.token'));
      const t = typeof token === 'string' ? token : (token && (token.value||token.token)) || '';
      const res = await fetch(${JSON.stringify(last.url)}, { headers: { Authorization: 'Bearer ' + t } });
      const j = await res.json();
      return JSON.stringify({status: res.status, total: j?.data?.total, items: (j?.data?.items||[]).length, first: j?.data?.items?.[0]?.name});`);
