  check('cap explanation shown at the limit', /at most 5/i.test(cartText), (cartText.match(/[^\n]*at most 5[^\n]*/i) || [''])[0]);
  const plusDisabled = await s.eval(`return [...document.querySelectorAll('button')].filter(b=>b.disabled).map(b=>b.title||b.innerText).filter(t=>/at most 5/i.test(t)).length`);
  check('"+" disabled with a reason at the limit', plusDisabled > 0, 'count=' + plusDisabled);
  await go('/'); await sleep(1500);
  const cardAddDisabled = await s.eval(`return [...document.querySelectorAll('article button.wb-btn-primary')].filter(b=>b.disabled).length`);
  check('menu "Add to Cart" buttons disabled at the limit', cardAddDisabled > 0, 'disabled=' + cardAddDisabled);
  await shot('17-cart-at-cap');

  // ---------------- 3. checkout + View Existing Order ----------------
  console.log('\n== checkout: View Existing Order ==');
  // reduce to a legal cart, then order
  await go('/cart'); await sleep(1200);
  // remove lines down to 1 portion using the qty select if present, else place with current
  await go('/checkout', 2200);
  await s.eval(`${SET} set('#address','Building A, Desk 101'); return true;`);
  await sleep(1800);
  const placeState = await s.eval(`const b=${byText('Place Order')}; return b? (b.disabled?'disabled':'enabled') : 'missing'`);
  check('Place Order is enabled with 5 items + address', placeState === 'enabled', placeState);
  if (placeState === 'enabled') {
    await s.eval(`const b=${byText('Place Order')}; b.click(); return true;`);
    const ok = await waitFor(`/order-success/.test(location.pathname)`, 25000);
    check('5-item order places successfully', ok, await s.eval(`return location.pathname`));
    const st = await s.eval(`return document.body.innerText`);
    check('success page shows the order number', /WB\d{8}-\d+/.test(st), (st.match(/WB\d{8}-\d+/) || [''])[0]);
    await shot('18-order-success-5items');
  }
  // now put an item back in the cart and revisit checkout -> button must flip
  await go('/'); await waitFor(`document.querySelectorAll('article').length>0`, 18000);
  await s.eval(`const b=document.querySelector('article button.wb-btn-primary'); if(b&&!b.disabled) b.click(); return true;`);
  await sleep(1200);
  await go('/checkout', 2200);
  const veoText = await s.eval(`return document.body.innerText`);
  const hasVeo = await s.eval(`return [...document.querySelectorAll('button,a')].some(e=>/View Existing Order/i.test(e.innerText))`);
