  if (hasVeo) {
    const target = await s.eval(`return [...document.querySelectorAll('button,a')].find(e=>/View Existing Order/i.test(e.innerText)).innerText`);
    check('button label is exactly "View Existing Order"', /^View Existing Order$/.test(target.trim()), JSON.stringify(target));
  }
  await shot('19-view-existing-order');

