  console.log('\n== Console category filter: wire-level ==');
  await s.eval(`localStorage.clear(); location.href='${APP}/login'; return true;`); await sleep(1800);
  await s.eval(`${SET} set('#login-email','admin@webox.com'); set('#login-password','Admin1234'); document.querySelector('form').requestSubmit(); return true;`);
  await waitFor(`location.pathname.startsWith('/console')`, 20000); await sleep(2200);
  s.reqs = []; s.resps = new Map();
  await s.eval(`const sel=document.querySelector('select[aria-label="Category"]');
    const d=Object.getOwnPropertyDescriptor(Object.getPrototypeOf(sel),'value');
    d.set.call(sel,'Japanese'); sel.dispatchEvent(new Event('change',{bubbles:true})); return true;`);
  await sleep(2500);
  const adminCalls = s.apiCalls().filter((c) => /\/api\/admin\/dishes/.test(c.url));
  for (const c of adminCalls) { const st = s.resps.get(c.id)?.status; console.log(`     ${st} ${c.url}`); }
  const rows = await s.eval(`return document.querySelectorAll('tbody tr').length`);
  const rowCats = await s.eval(`return [...document.querySelectorAll('tbody tr')].map(r=>r.children[3]?.innerText||'').join(',')`);
  check('Console category filter returns only that cuisine', rows > 0 && /Japanese/.test(rowCats) && !/Chinese|Western/.test(rowCats), `rows=${rows} cats=${rowCats}`);
  await shot('20-console-category-filter');

  // control: same URL replayed
  const lastA = adminCalls[adminCalls.length - 1];
  if (lastA) {
    const ctrl = await s.eval(`
      const t = JSON.parse(localStorage.getItem('webox.token'));
      const tok = typeof t==='string'?t:(t&&(t.value||t.token))||'';
      const res = await fetch(${JSON.stringify(lastA.url)}, { headers: { Authorization: 'Bearer ' + tok } });
      const j = await res.json();
      return JSON.stringify({status: res.status, total: j?.data?.total, items:(j?.data?.items||[]).length, cats:[...new Set((j?.data?.items||[]).map(i=>i.category))].join(',')});`);
    console.log('   replayed same URL in-page ->', ctrl);
  }

  const failed = results.filter((r) => !r.ok);
  console.log('\n' + '='.repeat(64));
  console.log(`WIRE-LEVEL CHECKS: ${results.length - failed.length}/${results.length} passed`);
  if (failed.length) { console.log('FAILURES:'); failed.forEach((f) => console.log('  - ' + f.n + ' :: ' + f.d)); }
  process.exit(failed.length ? 1 : 0);
})().catch((e) => { console.error('DRIVER ERROR:', e.message); process.exit(2); });
