{"content":"// Network-level diagnosis of the cuisine filter, plus re-tests that need proper pacing.
const CDP = process.env.CDP || 'http://127.0.0.1:9333';
const APP = process.env.APP || 'http://localhost:5173';
const SHOT = process.env.SHOT_DIR || '.';
const results = [];
function check(n, ok, d = '') { results.push({ n, ok: !!ok, d }); console.log(`${ok ? '[PASS]' : '[FAIL]'} ${n}${d ? '  -- ' + String(d).slice(0, 300) : ''}`); }

class S {
  constructor(ws) { this.ws = ws; this.id = 0; this.p = new Map(); this.reqs = []; this.resps = new Map(); }
  static async attach(u) {
    const ws = new WebSocket(u);
    await new Promise((r, j) => { ws.onopen = r; ws.onerror = j; });
    const s = new S(ws);
    ws.onmessage = (e) => {
      const m = JSON.parse(e.data);
      if (m.id && s.p.has(m.id)) { const { resolve, reject } = s.p.get(m.id); s.p.delete(m.id); m.error ? reject(new Error(JSON.stringify(m.error))) : resolve(m.result); return; }
      if (m.method === 'Network.requestWillBeSent') s.reqs.push({ id: m.params.requestId, url: m.params.request.url, method: m.params.request.method });
      if (m.method === 'Network.responseReceived') { const r = s.resps.get(m.params.requestId) || {}; r.status = m.params.response.status; s.resps.set(m.params.requestId, r); }
      if (m.method === 'Network.loadingFinished') { /* noop */ }
    };
    return s;
  }
  send(method, params = {}) { const id = ++this.id; return new Promise((res, rej) => { this.p.set(id, { resolve: res, reject: rej }); this.ws.send(JSON.stringify({ id, method, params })); setTimeout(() => { if (this.p.has(id)) { this.p.delete(id); rej(new Error('timeout ' + method)); } }, 30000); }); }
  async eval(e) { const r = await this.send('Runtime.evaluate', { expression: `(async()=>{${e}})()`, awaitPromise: true, returnByValue: true }); if (r.exceptionDetails) throw new Error(r.exceptionDetails.exception?.description); return r.result.value; }
  async body(id) { try { const r = await this.send('Network.getResponseBody', { requestId: id }); return r.body; } catch { return null; } }
  apiCalls() { return this.reqs.filter((r) => /\/api\//.test(r.url)); }
}
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const SET = `const set=(sel,v)=>{const el=document.querySelector(sel); if(!el) return false;
  const d=Object.getOwnPropertyDescriptor(Object.getPrototypeOf(el),'value');
  d.set.call(el,v); el.dispatchEvent(new Event('input',{bubbles:true})); el.dispatchEvent(new Event('change',{bubbles:true})); return true;};`;
const byText = (t) => `[...document.querySelectorAll('button,a')].find(e=>e.innerText.trim()===${JSON.stringify(t)})`;

(async () => {
  const t = (await (await fetch(CDP + '/json')).json()).find((x) => x.type === 'page');
  const s = await S.attach(t.webSocketDebuggerUrl);
  await s.send('Page.enable'); await s.send('Runtime.enable'); await s.send('Network.enable');
  const shot = async (n) => { const r = await s.send('Page.captureScreenshot', {}); (await import('node:fs')).writeFileSync(`${SHOT}\\${n}.png`, Buffer.from(r.data, 'base64')); };
  const go = async (p, ms = 1500) => { await s.eval(`location.href='${APP}${p}'; return true;`); await sleep(ms); };
  const waitFor = async (e, ms = 15000) => { const t0 = Date.now(); while (Date.now() - t0 < ms) { try { if (await s.eval(`return !!(${e})`)) return true; } catch { } await sleep(200); } return false; };

  const email = `ui3.${Math.random().toString(16).slice(2, 10)}@example.com`;
  const pw = 'Passw0rd123';
  await s.eval(`localStorage.clear(); sessionStorage.clear(); location.href='${APP}/register'; return true;`); await sleep(2200);
  await waitFor(`document.querySelector('#reg-email')`, 20000);
  await s.eval(`${SET} set('#reg-email','${email}'); set('#reg-name','UI Auditor 3'); set('#reg-password','${pw}'); set('#reg-confirm','${pw}'); return true;`);
  await s.eval(`document.querySelector('form').requestSubmit(); return true;`);
  await waitFor(`location.pathname==='/'`, 20000);

  // ---------------- 1. cuisine filter, with the wire captured ----------------
  console.log('\n== cuisine filter: wire-level diagnosis ==');
  await go('/'); await waitFor(`document.querySelectorAll('article').length>0`, 20000);
  const base = await s.eval(`return document.querySelectorAll('article').length`);
  s.reqs = []; s.resps = new Map();
  await s.eval(`const b=${byText('Chinese')}; b.click(); return true;`);
  await sleep(2500);
  const calls = s.apiCalls().filter((c) => /\/api\/menu\?/.test(c.url));
  console.log('   captured menu calls:');
  for (const c of calls) { const st = s.resps.get(c.id)?.status; console.log(`     ${st} ${c.url}`); }
  const last = calls[calls.length - 1];
  let bodySnippet = '';
  if (last) { const b = await s.body(last.id); bodySnippet = (b || '').slice(0, 200); console.log('     body:', bodySnippet); }
  const count = await s.eval(`return document.querySelectorAll('article').length`);
  check('cuisine filter returns dishes', count > 0, `before=${base} after=${count}`);

  // Direct-API control: same request the UI sent, replayed with curl-like fetch
  if (last) {
    const ctrl = await s.eval(`
      const token = JSON.parse(localStorage.getItem('webox.token'));
      const t = typeof token === 'string' ? token : (token && (token.value||token.token)) || '';
      const res = await fetch(${JSON.stringify(last.url)}, { headers: { Authorization: 'Bearer ' + t } });
      const j = await res.json();
      return JSON.stringify({status: res.status, total: j?.data?.total, items: (j?.data?.items||[]).length, first: j?.data?.items?.[0]?.name});`);
    console.log('   replayed same URL in-page ->', ctrl);
  }

  // ---------------- 2. cart cap with correct pacing ----------------
  console.log('\n== cart cap (paced clicks) ==');
  await go('/'); await waitFor(`document.querySelectorAll('article').length>0`, 20000);
  for (let i = 0; i < 5; i++) {
    await s.eval(`const b=document.querySelector('article button.wb-btn-primary'); if(b && !b.disabled) b.click(); return true;`);
    await sleep(700); // respect the 400ms single-flight cooldown
  }
  await sleep(1000);
  await go('/cart'); await sleep(1500);
  const cartText = await s.eval(`return document.body.innerText`);
  check('cart counter reaches 5 / 5 items', /5\s*\/\s*5\s*items/.test(cartText), (cartText.match(/\d\s*\/\s*5\s*items/) || [''])[0]);
  check('cap explanation shown at the limit', /at most 5/i.test(cartText), (cartText.match(/[^\n]*at most 5[^\n]*/i) || [''])[0]);
  const plusDisabled = await s.eval(`return [...document.querySelectorAll('button')].filter(b=>b.disabled).map(b=>b.title||b.innerText).filter(t=>/at most 5/i.test(t)).length`);
  check('"+" disabled with a reason at the limit', plusDisabled > 0, 'count=' + plusDisabled);
  await go('/'); await sleep(1500);
  const cardAddDisabled = await s.eval(`return [...document.querySelectorAll('article button.wb-btn-primary')].filter(b=>b.disabled).length`);
  check('menu "Add to Cart" buttons disabled at the limit', cardAddDisabled > 0, 'disabled=' + cardAddDisabled);
  await shot('17-cart-at-cap');

  // ---------------- 3. checkout + View Existing Order ----------------
  console.log('\n== checkout: View Existing Order ==');
  // reduce to a legal cart, then order
  await go('/cart'); await sleep(1200);
  // remove lines down to 1 portion using the qty select if present, else place with current
  await go('/checkout', 2200);
  await s.eval(`${SET} set('#address','Building A, Desk 101'); return true;`);
  await sleep(1800);
  const placeState = await s.eval(`const b=${byText('Place Order')}; return b? (b.disabled?'disabled':'enabled') : 'missing'`);
  check('Place Order is enabled with 5 items + address', placeState === 'enabled', placeState);
  if (placeState === 'enabled') {
    await s.eval(`const b=${byText('Place Order')}; b.click(); return true;`);
    const ok = await waitFor(`/order-success/.test(location.pathname)`, 25000);
    check('5-item order places successfully', ok, await s.eval(`return location.pathname`));
    const st = await s.eval(`return document.body.innerText`);
    check('success page shows the order number', /WB\d{8}-\d+/.test(st), (st.match(/WB\d{8}-\d+/) || [''])[0]);
    await shot('18-order-success-5items');
  }
  // now put an item back in the cart and revisit checkout -> button must flip
  await go('/'); await waitFor(`document.querySelectorAll('article').length>0`, 18000);
  await s.eval(`const b=document.querySelector('article button.wb-btn-primary'); if(b&&!b.disabled) b.click(); return true;`);
  await sleep(1200);
  await go('/checkout', 2200);
  const veoText = await s.eval(`return document.body.innerText`);
  const hasVeo = await s.eval(`return [...document.querySelectorAll('button,a')].some(e=>/View Existing Order/i.test(e.innerText))`);
  check('checkout flips the button to "View Existing Order"', hasVeo,
    veoText.split('\n').filter((l) => l.trim()).slice(0, 6).join(' / '));
  if (hasVeo) {
    const target = await s.eval(`return [...document.querySelectorAll('button,a')].find(e=>/View Existing Order/i.test(e.innerText)).innerText`);
    check('button label is exactly "View Existing Order"', /^View Existing Order$/.test(target.trim()), JSON.stringify(target));
  }
  await shot('19-view-existing-order');

  // ---------------- 4. Console category filter, wire captured ----------------
  console.log('\n== Console category filter: wire-level ==');
  await s.eval(`localStorage.clear(); location.href='${APP}/login'; return true;`); await sleep(1800);
  await s.eval(`${SET} set('#login-email','admin@webox.com'); set('#login-password','Admin1234'); document.querySelector('form').requestSubmit(); return true;`);
  await waitFor(`location.pathname.startsWith('/console')`, 20000); await sleep(2200);
  s.reqs = []; s.resps = new Map();
  await s.eval(`const sel=document.querySelector('select[aria-label="Category"]');
    const d=Object.getOwnPropertyDescriptor(Object.getPrototypeOf(sel),'value');
    d.set.call(sel,'Japanese'); sel.dispatchEvent(new Event('change',{bubbles:true})); return true;`);
  await sleep(2500);
  const adminCalls = s.apiCalls().filter((c) => /\/api\/admin\/dishes/.test(c.url));
  for (const c of adminCalls) { const st = s.resps.get(c.id)?.status; console.log(`     ${st} ${c.url}`); }
  const rows = await s.eval(`return document.querySelectorAll('tbody tr').length`);
  const rowCats = await s.eval(`return [...document.querySelectorAll('tbody tr')].map(r=>r.children[3]?.innerText||'').join(',')`);
  check('Console category filter returns only that cuisine', rows > 0 && /Japanese/.test(rowCats) && !/Chinese|Western/.test(rowCats), `rows=${rows} cats=${rowCats}`);
  await shot('20-console-category-filter');

  // control: same URL replayed
  const lastA = adminCalls[adminCalls.length - 1];
  if (lastA) {
    const ctrl = await s.eval(`
      const t = JSON.parse(localStorage.getItem('webox.token'));
      const tok = typeof t==='string'?t:(t&&(t.value||t.token))||'';
      const res = await fetch(${JSON.stringify(lastA.url)}, { headers: { Authorization: 'Bearer ' + tok } });
      const j = await res.json();
      return JSON.stringify({status: res.status, total: j?.data?.total, items:(j?.data?.items||[]).length, cats:[...new Set((j?.data?.items||[]).map(i=>i.category))].join(',')});`);
    console.log('   replayed same URL in-page ->', ctrl);
  }

  const failed = results.filter((r) => !r.ok);
  console.log('\n' + '='.repeat(64));
  console.log(`WIRE-LEVEL CHECKS: ${results.length - failed.length}/${results.length} passed`);
  if (failed.length) { console.log('FAILURES:'); failed.forEach((f) => console.log('  - ' + f.n + ' :: ' + f.d)); }
  process.exit(failed.length ? 1 : 0);
})().catch((e) => { console.error('DRIVER ERROR:', e.message); process.exit(2); });
