{"command":"$BU='http://localhost:8080'
function Api($m,$p,$h=@{},$b=$null){
  $pr=@{Method=$m;Uri=$BU+$p;Headers=$h;UseBasicParsing=$true}
  if($b){$pr.ContentType='application/json';$pr.Body=($b|ConvertTo-Json -Depth 12 -Compress)}
  try{$r=Invoke-WebRequest @pr; return [pscustomobject]@{S=[int]$r.StatusCode;R=[string]$r.Content}}
  catch{$rp=$_.Exception.Response; if(!$rp){return [pscustomobject]@{S=0;R=$_.Exception.Message}}; $sr=New-Object IO.StreamReader($rp.GetResponseStream()); return [pscustomobject]@{S=[int]$rp.StatusCode;R=$sr.ReadToEnd()}}
}
$suf=[guid]::NewGuid().ToString('N').Substring(0,8)
$tok=((Api POST '/api/auth/register' @{} @{email="iso.$suf@example.com";password="Passw0rd123";displayName="Iso"}).R|ConvertFrom-Json).data.token
$H=@{Authorization="Bearer $tok"}
$d=(Get-Date).ToString('yyyy-MM-dd')

Write-Output "=== ISOLATION MATRIX ==="
$cases=@(
  "/api/menu?date=$d&page=0&size=12",
  "/api/menu?date=$d&categories=Chinese&page=0&size=12",
  "/api/menu?date=$d&categories=Chinese&size=12",
  "/api/menu?date=$d&categories=Chinese&size=50",
  "/api/menu?date=$d&categories=Chinese",
  "/api/menu?date=$d&categories=Chinese&categories=Japanese&size=50",
  "/api/menu?date=$d&categories=Chinese&categories=Japanese&page=0&size=12",
  "/api/menu?date=$d&categories=Light%20Meal&page=0&size=12",
  "/api/menu?date=$d&categories=Light+Meal&page=0&size=12"
)
foreach($c in $cases){
  $r=Api GET $c $H
  $extra=''
  if($r.S -ne 200){ $j=$r.R|ConvertFrom-Json; $extra=" code=$($j.code)"; if($j.data.fieldErrors){ $extra += " fields=" + (($j.data.fieldErrors.PSObject.Properties|ForEach-Object{"$($_.Name):$($_.Value)"}) -join '; ') } }
  "{0,-4} {1}{2}" -f $r.S,$c,$extra
}","description":"Isolate the cuisine filter 400 error","timeoutMs":180000}

