const APP = process.env.APP || 'http://localhost:5173';
const SHOT = process.env.SHOT_DIR || '.';
const results = [];
function check(n, ok, d = '') { results.push({ n, ok: !!ok, d }); console.log(`${ok ? '[PASS]' : '[FAIL]'} ${n}${d ? '  -- ' + String(d).slice(0, 220) : ''}`); }
class S {
  constructor(ws) { this.ws = ws; this.id = 0; this.p = new Map(); }
  static async attach(u) { const ws = new WebSocket(u); await new Promise((r, j) => { ws.onopen = r; ws.onerror = j; }); const s = new S(ws); ws.onmessage = (e) => { const m = JSON.parse(e.data); if (m.id && s.p.has(m.id)) { const { resolve, reject } = s.p.get(m.id); s.p.delete(m.id); m.error ? reject(new Error(JSON.stringify(m.error))) : resolve(m.result); } }; return s; }
  send(method, params = {}) { const id = ++this.id; return new Promise((res, rej) => { this.p.set(id, { resolve: res, reject: rej }); this.ws.send(JSON.stringify({ id, method, params })); setTimeout(() => { if (this.p.has(id)) { this.p.delete(id); rej(new Error('timeout ' + method)); } }, 30000); }); }
  async eval(e) { const r = await this.send('Runtime.evaluate', { expression: `(async()=>{${e}})()`, awaitPromise: true, returnByValue: true }); if (r.exceptionDetails) throw new Error(r.exceptionDetails.exception?.description); return r.result.value; }
}
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const SET = `const set=(sel,v)=>{const el=document.querySelector(sel); if(!el) return false;
  const d=Object.getOwnPropertyDescriptor(Object.getPrototypeOf(el),'value');
  d.set.call(el,v); el.dispatchEvent(new Event('input',{bubbles:true})); el.dispatchEvent(new Event('change',{bubbles:true})); return true;};`;

(async () => {
  const t = (await (await fetch(CDP + '/json')).json()).find((x) => x.type === 'page');
  const s = await S.attach(t.webSocketDebuggerUrl);
  await s.send('Page.enable'); await s.send('Runtime.enable');
  const shot = async (n) => { const r = await s.send('Page.captureScreenshot', {}); (await import('node:fs')).writeFileSync(`${SHOT}\\${n}.png`, Buffer.from(r.data, 'base64')); };
  const go = async (p, ms = 1600) => { await s.eval(`location.href='${APP}${p}'; return true;`); await sleep(ms); };
  const waitFor = async (e, ms = 18000) => { const t0 = Date.now(); while (Date.now() - t0 < ms) { try { if (await s.eval(`return !!(${e})`)) return true; } catch { } await sleep(200); } return false; };

  const email = `ui5.${Math.random().toString(16).slice(2, 10)}@example.com`;
  const pw = 'Passw0rd123';
  await s.eval(`localStorage.clear(); sessionStorage.clear(); location.href='${APP}/register'; return true;`); await sleep(2200);
  await waitFor(`document.querySelector('#reg-email')`, 20000);
  await s.eval(`${SET} set('#reg-email','${email}'); set('#reg-name','UI Auditor 5'); set('#reg-password','${pw}'); set('#reg-confirm','${pw}'); return true;`);
  await s.eval(`document.querySelector('form').requestSubmit(); return true;`);
  await waitFor(`location.pathname==='/'`, 20000);

  console.log('\n== flag allergens on the preferences page ==');
  await go('/settings', 2400);
  const chips = await s.eval(`return JSON.stringify([...document.querySelectorAll('button')].map(b=>b.innerText.trim()).filter(t=>/Peanuts|Dairy|Egg|Gluten|Soy|Fish|Shellfish/.test(t)))`);
  console.log('   allergen chips:', chips);
  const flagged = await s.eval(`
    const want=['Peanuts','Egg'];
    const btns=[...document.querySelectorAll('button')].filter(b=>want.includes(b.innerText.trim()));
    btns.forEach(b=>b.click());
    return btns.map(b=>b.innerText.trim()).join(',');`);
  await sleep(900);
  check('allergen chips are clickable toggle buttons', flagged.length > 0, 'flagged=' + flagged);
  const saveLabel = await s.eval(`const b=[...document.querySelectorAll('button')].find(x=>/Save preferences/i.test(x.innerText)); if(b){b.click(); return b.innerText.trim();} return 'missing'`);
  await sleep(2500);
  const okToast = await s.eval(`return !!document.querySelector('[class*=toast],[role=status],.fixed')`);
  check('preferences save triggers feedback', saveLabel !== 'missing', 'save="' + saveLabel + '" feedback=' + okToast);
  await shot('26-preferences-saved');

  // verify it persisted through the API
  const persisted = await s.eval(`
    const tok=localStorage.getItem('webox.token');
    const r=await fetch('/api/users/me/preferences',{headers:{Authorization:'Bearer '+tok}});
    const j=await r.json();
    return JSON.stringify({status:r.status, allergens:j?.data?.allergens});`);
  check('flagged allergens persisted server-side', /Peanuts/.test(persisted) && /Egg/.test(persisted), persisted);

  console.log('\n== add a dish containing a flagged allergen ==');
  await go('/'); await waitFor(`document.querySelectorAll('article').length>0`, 20000);
  const cardInfo = await s.eval(`
    const cards=[...document.querySelectorAll('article')];
    const c=cards.find(x=>/Contains:/i.test(x.innerText));
    if(!c) return 'none-flagged';
    const name=c.querySelector('h3').innerText;
    c.querySelector('button.wb-btn-primary').click();
    return name;`);
  await sleep(2000);
  const dlgText = await s.eval(`return document.body.innerText`);
  const modal = await s.eval(`return {
    hasModal: !!document.querySelector('.fixed.inset-0'),
    title: (document.querySelector('.fixed.inset-0 h2, .fixed.inset-0 h3')?.innerText||''),
    body: (document.body.innerText.match(/This dish contains[^\\n]*/)||[''])[0],
    buttons: [...document.querySelectorAll('.fixed.inset-0 button')].map(b=>b.innerText.trim()).join(' | ')
  }`);
  check('a flagged-allergen dish is still shown on the menu (never hidden)', cardInfo !== 'none-flagged', 'dish=' + cardInfo);
  check('warning dialog appears on add', modal.hasModal, JSON.stringify(modal));
  check('dialog wording matches the PRD sentence', /This dish contains an allergen you flagged: \[.*\]\. Add anyway\?/.test(modal.body), modal.body);
  check('dialog offers Cancel / Add anyway', /Cancel/.test(modal.buttons) && /Add anyway/.test(modal.buttons), modal.buttons);
  await shot('27-allergen-dialog');

  // confirm the add still works after the warning
  const confirmed = await s.eval(`const b=[...document.querySelectorAll('.fixed.inset-0 button')].find(x=>/Add anyway/i.test(x.innerText)); if(b){b.click(); return true;} return false;`);
  await sleep(1500);
  await go('/cart'); await sleep(1500);
  const inCart = await s.eval(`return document.body.innerText`);
  check('"Add anyway" completes the add', confirmed && /¥\s?\d+\.\d{2}/.test(inCart), 'cart=' + inCart.split('\n').filter((l) => l.trim()).slice(0, 4).join(' / '));

  // cancel path must not add
  await go('/'); await waitFor(`document.querySelectorAll('article').length>0`, 18000);
  const before = await s.eval(`const t=localStorage.getItem('webox.cart'); return t?JSON.parse(t).length:0;`);
  await s.eval(`
    const cards=[...document.querySelectorAll('article')];
    const c=cards.find(x=>/Contains:/i.test(x.innerText)) || cards[1];
    c.querySelector('button.wb-btn-primary').click(); return true;`);
  await sleep(1600);
  const cancelled = await s.eval(`const b=[...document.querySelectorAll('.fixed.inset-0 button')].find(x=>/Cancel/i.test(x.innerText)); if(b){b.click(); return true;} return false;`);
  await sleep(1200);
  const after = await s.eval(`const t=localStorage.getItem('webox.cart'); return t?JSON.parse(t).length:0;`);
  check('Cancel on the warning does not add the dish', !cancelled || after === before, `before=${before} after=${after} cancelled=${cancelled}`);

  const failed = results.filter((r) => !r.ok);
  console.log('\n' + '='.repeat(64));
  console.log(`ALLERGEN UI CHECKS: ${results.length - failed.length}/${results.length} passed`);
  if (failed.length) { console.log('FAILURES:'); failed.forEach((f) => console.log('  - ' + f.n + ' :: ' + f.d)); }
  process.exit(failed.length ? 1 : 0);
})().catch((e) => { console.error('DRIVER ERROR:', e.message); process.exit(2); });
