    private final DishCategoryRequestConverter converter = new DishCategoryRequestConverter();

    @ParameterizedTest
    @CsvSource({
            "Chinese, CHINESE",
            "Western, WESTERN",
            "Japanese, JAPANESE",
            "Korean, KOREAN",
            "Light Meal, LIGHT_MEAL",
            "Southeast Asian, SOUTHEAST_ASIAN"
    })
