{"command":"$ErrorActionPreference='Stop'
$BaseUrl='http://localhost:8080'
function Invoke-Api {
    param([string]$Method="GET",[string]$Path,[hashtable]$Headers=@{},$Body=$null)
    $uri=$BaseUrl+$Path
    $params=@{Method=$Method;Uri=$uri;Headers=$Headers;UseBasicParsing=$true}
    if($null -ne $Body){$params.ContentType="application/json; charset=utf-8";$params.Body=($Body|ConvertTo-Json -Depth 10 -Compress)}
    try{
        $response=Invoke-WebRequest @params
        $text=if($response.Content -is [byte[]]){[Text.Encoding]::UTF8.GetString($response.Content)}else{[string]$response.Content}
        return [pscustomobject]@{Status=[int]$response.StatusCode;Body=($text|ConvertFrom-Json);Raw=$text}
    }catch{
        $resp=$_.Exception.Response
        if($null -eq $resp){throw}
        $reader=New-Object System.IO.StreamReader($resp.GetResponseStream()); $text=$reader.ReadToEnd()
        $parsed=$null; try{$parsed=$text|ConvertFrom-Json}catch{}
        return [pscustomobject]@{Status=[int]$resp.StatusCode;Body=$parsed;Raw=$text}
    }
}
function Assert-That([string]$Name,[bool]$Condition,[string]$Detail=""){ "  [{0}] {1} {2}" -f $(if($Condition){'PASS'}else{'FAIL'}),$Name,$Detail }

$suf=[guid]::NewGuid().ToString('N').Substring(0,8)
$reg=Invoke-Api -Method Post -Path "/api/auth/register" -Body @{email="nv.$suf@example.com";password="Passw0rd123";displayName="NV"}
$H=@{Authorization="Bearer $($reg.Body.data.token)"}
$d=(Get-Date).ToString('yyyy-MM-dd')

Write-Output "### 场景 A：修复后（真实 200）—— 新断言应全部 PASS"
$good = Invoke-Api -Path "/api/menu?date=$d&categories=Japanese&size=50" -Headers $H
"  (HTTP $($good.Status), total=$($good.Body.data.total))"
Assert-That "single cuisine filter is accepted" ($good.Status -eq 200)
$gcats=@($good.Body.data.items|ForEach-Object{$_.category}|Sort-Object -Unique)
Assert-That "single cuisine filter returns only that cuisine" (($gcats -join ',') -eq "Japanese") "got=$($gcats -join ',')"

Write-Output ""
Write-Output "### 场景 B：模拟修复前（真实 400，走同一段代码路径）—— 新断言应全部 FAIL"
$bad = Invoke-Api -Path "/api/menu?date=$d&categories=Seafood&size=50" -Headers $H
"  (HTTP $($bad.Status), body=$($bad.Raw))"
Assert-That "single cuisine filter is accepted" ($bad.Status -eq 200)
$bcats=@($bad.Body.data.items|ForEach-Object{$_.category}|Sort-Object -Unique)
Assert-That "single cuisine filter returns only that cuisine" (($bcats -join ',') -eq "Japanese") "got=$($bcats -join ',')"

Write-Output ""
Write-Output "### 对照：修复前的旧断言在同一个 400 上会怎样"
$unexpected = ($bcats | Where-Object { $_ -ne "Chinese" -and $_ -ne "Japanese" }).Count
"  旧断言谓词 (unexpected -eq 0) => $($unexpected -eq 0)   <-- 400 时依然为 True，即假通过"
