{"content":"// Acceptance test for the cuisine-filter fix, driven through the real SPA.
const CDP = 'http://127.0.0.1:9333';
const APP = 'http://localhost:5173';
const SHOT = process.env.SHOT_DIR || '.';
const results = [];
function check(n, ok, d = '') { results.push({ n, ok: !!ok, d }); console.log(`${ok ? '[PASS]' : '[FAIL]'} ${n}${d ? '  -- ' + String(d).slice(0, 200) : ''}`); }
class S {
  constructor(ws) { this.ws = ws; this.id = 0; this.p = new Map(); this.reqs = []; this.resps = new Map(); }
  static async attach(u) {
    const ws = new WebSocket(u); await new Promise((r, j) => { ws.onopen = r; ws.onerror = j; });
    const s = new S(ws);
    ws.onmessage = (e) => {
      const m = JSON.parse(e.data);
      if (m.id && s.p.has(m.id)) { const { resolve, reject } = s.p.get(m.id); s.p.delete(m.id); m.error ? reject(new Error(JSON.stringify(m.error))) : resolve(m.result); return; }
      if (m.method === 'Network.requestWillBeSent' && /\/api\/menu\?/.test(m.params.request.url)) s.reqs.push({ id: m.params.requestId, url: m.params.request.url });
      if (m.method === 'Network.responseReceived') { const r = s.resps.get(m.params.requestId) || {}; r.status = m.params.response.status; s.resps.set(m.params.requestId, r); }
    };
    return s;
  }
  send(method, params = {}) { const id = ++this.id; return new Promise((res, rej) => { this.p.set(id, { resolve: res, reject: rej }); this.ws.send(JSON.stringify({ id, method, params })); setTimeout(() => { if (this.p.has(id)) { this.p.delete(id); rej(new Error('timeout ' + method)); } }, 30000); }); }
  async eval(e) { const r = await this.send('Runtime.evaluate', { expression: `(async()=>{${e}})()`, awaitPromise: true, returnByValue: true }); if (r.exceptionDetails) throw new Error(r.exceptionDetails.exception?.description); return r.result.value; }
}
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const SET = `const set=(sel,v)=>{const el=document.querySelector(sel); if(!el) return false;
  const d=Object.getOwnPropertyDescriptor(Object.getPrototypeOf(el),'value');
  d.set.call(el,v); el.dispatchEvent(new Event('input',{bubbles:true})); el.dispatchEvent(new Event('change',{bubbles:true})); return true;};`;
const byText = (t) => `[...document.querySelectorAll('button,a')].find(e=>e.innerText.trim()===${JSON.stringify(t)})`;
const cats = `[...new Set([...document.querySelectorAll('article .wb-chip')].map(e=>e.innerText.trim()))].filter(t=>['Chinese','Western','Japanese','Light Meal','Korean','Southeast Asian'].includes(t))`;

(async () => {
  const t = (await (await fetch(CDP + '/json')).json()).find((x) => x.type === 'page');
  const s = await S.attach(t.webSocketDebuggerUrl);
  await s.send('Page.enable'); await s.send('Runtime.enable'); await s.send('Network.enable');
  const shot = async (n) => { const r = await s.send('Page.captureScreenshot', {}); (await import('node:fs')).writeFileSync(`${SHOT}\\${n}.png`, Buffer.from(r.data, 'base64')); };
  const go = async (p, ms = 1600) => { await s.eval(`location.href='${APP}${p}'; return true;`); await sleep(ms); };
  const waitFor = async (e, ms = 20000) => { const t0 = Date.now(); while (Date.now() - t0 < ms) { try { if (await s.eval(`return !!(${e})`)) return true; } catch { } await sleep(200); } return false; };

  // register + land on the menu
  await s.eval(`localStorage.clear(); sessionStorage.clear(); location.href='${APP}/register'; return true;`); await sleep(2200);
  await waitFor(`document.querySelector('#reg-email')`);
  await s.eval(`${SET} set('#reg-email','accept.${Math.random().toString(16).slice(2,10)}@example.com'); set('#reg-name','Acceptance'); set('#reg-password','Passw0rd123'); set('#reg-confirm','Passw0rd123'); return true;`);
  await s.eval(`document.querySelector('form').requestSubmit(); return true;`);
  await waitFor(`location.pathname==='/'`);
  await waitFor(`document.querySelectorAll('article').length>0`);
  const baseline = await s.eval(`return document.querySelectorAll('article').length`);
  check('menu loads before filtering', baseline > 0, 'cards=' + baseline);

  // --- single cuisine ---
  s.reqs = []; s.resps = new Map();
  await s.eval(`const b=${byText('Japanese')}; b.click(); return true;`);
  await sleep(2500);
  const wire = s.reqs.map((c) => `${s.resps.get(c.id)?.status} ${c.url.split('/api')[1]}`).slice(-1)[0];
  const afterJp = await s.eval(`return {count: document.querySelectorAll('article').length, cats: ${cats}.join(',')}`);
  check('clicking "Japanese" returns dishes (was: empty list)', afterJp.count > 0, `wire: ${wire} | ${JSON.stringify(afterJp)}`);
  check('"Japanese" filter shows only Japanese', afterJp.cats === 'Japanese', afterJp.cats);
  await shot('28-cuisine-filter-fixed');

  // --- multi-select incl. a label with a space ---
  await s.eval(`const b=${byText('Chinese')}; b.click(); return true;`);
  await sleep(2000);
  const multi1 = await s.eval(`return {count: document.querySelectorAll('article').length, cats: ${cats}.sort().join(',')}`);
  check('multi-select Chinese + Japanese works', multi1.cats === 'Chinese,Japanese', JSON.stringify(multi1));

  await s.eval(`const b=${byText('Light Meal')}; b.click(); return true;`);
  await sleep(2000);
  const multi2 = await s.eval(`return {count: document.querySelectorAll('article').length, cats: ${cats}.sort().join(',')}`);
  check('multi-select including "Light Meal" (space in label) works', /Light Meal/.test(multi2.cats) && multi2.count > 0, JSON.stringify(multi2));
  await shot('29-cuisine-multiselect-fixed');

  // --- clear ---
  const cleared = await s.eval(`const b=[...document.querySelectorAll('button')].find(x=>/Clear filters/i.test(x.innerText)); if(b){b.click(); return true;} return false;`);
  await sleep(2200);
  const afterClear = await s.eval(`return {count: document.querySelectorAll('article').length, cats: ${cats}.sort().join(',')}`);
  check('clearing filters restores the full menu', cleared && afterClear.cats.split(',').length > 2, JSON.stringify(afterClear));

  // --- Console category filter ---
  await s.eval(`localStorage.clear(); location.href='${APP}/login'; return true;`); await sleep(1800);
  await s.eval(`${SET} set('#login-email','admin@webox.com'); set('#login-password','Admin1234'); document.querySelector('form').requestSubmit(); return true;`);
  await waitFor(`location.pathname.startsWith('/console')`); await sleep(2200);
  const rowsBefore = await s.eval(`return document.querySelectorAll('tbody tr').length`);
  s.reqs = []; s.resps = new Map();
  await s.eval(`const sel=document.querySelector('select[aria-label="Category"]');
    const d=Object.getOwnPropertyDescriptor(Object.getPrototypeOf(sel),'value');
    d.set.call(sel,'Japanese'); sel.dispatchEvent(new Event('change',{bubbles:true})); return true;`);
  await sleep(2500);
  const adminWire = s.reqs.map((c) => `${s.resps.get(c.id)?.status} ${c.url.split('/api')[1]}`).slice(-1)[0];
  const adminRes = await s.eval(`return {rows: document.querySelectorAll('tbody tr').length,
    cats: [...new Set([...document.querySelectorAll('tbody tr')].map(r=>r.children[3]?.innerText||''))].join(',')}`);
  check('Console category filter returns rows (was: 0)', adminRes.rows > 0, `wire: ${adminWire} | ${JSON.stringify(adminRes)}`);
  check('Console category filter shows only Japanese', adminRes.cats === 'Japanese', adminRes.cats);
  await shot('30-console-category-fixed');

  const failed = results.filter((r) => !r.ok);
  console.log('\n' + '='.repeat(64));
  console.log(`ACCEPTANCE: ${results.length - failed.length}/${results.length} passed`);
  if (failed.length) { console.log('FAILURES:'); failed.forEach((f) => console.log('  - ' + f.n + ' :: ' + f.d)); }
  process.exit(failed.length ? 1 : 0);
})().catch((e) => { console.error('DRIVER ERROR:', e.message); process.exit(2); });
","file_path":"C:\Users\liujibiao\AppData\Local\Temp\webox-accept\accept.mjs"}

