  const waitFor = async (e, ms = 20000) => { const t0 = Date.now(); while (Date.now() - t0 < ms) { try { if (await s.eval(`return !!(${e})`)) return true; } catch { } await sleep(200); } return false; };

  await s.eval(`location.href='${APP}/login'; return true;`); await sleep(2500);
  await s.eval(`try{localStorage.clear();}catch(e){} return true;`); await sleep(300);
  const set = `const set=(sel,v)=>{const el=document.querySelector(sel);const d=Object.getOwnPropertyDescriptor(Object.getPrototypeOf(el),'value');d.set.call(el,v);el.dispatchEvent(new Event('input',{bubbles:true}));};`;
  await s.eval(`${set} set('#login-email','admin@webox.com'); set('#login-password','Admin1234'); document.querySelector('form').requestSubmit(); return true;`);
  await waitFor(`location.pathname.startsWith('/console')`); await sleep(2500);

  const headers = await s.eval(`return [...document.querySelectorAll('thead th')].map(th=>th.innerText.trim()).join(' | ')`);
  console.log('Console 表头:', headers);

  await s.eval(`const sel=document.querySelector('select[aria-label="Category"]');
    const d=Object.getOwnPropertyDescriptor(Object.getPrototypeOf(sel),'value');
    d.set.call(sel,'Japanese'); sel.dispatchEvent(new Event('change',{bubbles:true})); return true;`);
  await sleep(2800);

  const rows = await s.eval(`return [...document.querySelectorAll('tbody tr')].map(r=>[...r.children].map(c=>c.innerText.trim()).join(' / '))`);
  console.log('\n过滤后的行:');
  rows.forEach((r) => console.log('   ' + r));
  const catIdx = headers.split(' | ').indexOf('Category');
  const cats = [...new Set(rows.map((r) => r.split(' / ')[catIdx]))];
  console.log(`\nCategory 列(索引 ${catIdx}) 取值: [${cats.join(', ')}]`);
  console.log(cats.length === 1 && cats[0] === 'Japanese' ? '[PASS] Console 分类筛选只返回 Japanese' : '[FAIL] ' + cats.join(','));
  process.exit(cats.length === 1 && cats[0] === 'Japanese' ? 0 : 1);
})().catch((e) => { console.error('ERR', e.message); process.exit(2); });
